TN.defSec("trauma",{"major-trauma-adult":{"id":"major-trauma-adult","variants":[{"id":"trauma-adult-stable","o":{"I":[{"t":"eFAST (screen for shock causes) immediately after primary survey; CXR portable and pelvis radiograph; CT head noncontrast (TBI), CT cervical spine, CT chest / abdomen / pelvis with IV contrast when hemodynamically stable"},{"t":"Log-roll with in-line stabilization for spine; extremity radiographs for deformity"}],"L":[{"t":"Type and screen (crossmatch if bleeding), CBC, BMP, PT/INR, PTT, lactate, ABG, glucose (capillary), ethanol / toxicology, urinalysis (hematuria), pregnancy test (females), CK"}],"S":[{"t":"Two large-bore IV lines; warm crystalloid if indicated","fl":[{"k":"ci","v":"avoid over-resuscitation"}]},{"t":"Tranexamic acid IV early (may reduce mortality) in significant bleeding"},{"t":"Analgesia (IV opioid titrated)"}],"T":[{"t":"Continuous monitoring (ECG, SpO2, capnography if intubated); keep normothermic; in-line cervical stabilization"},{"t":"Tetanus update; immobilize fractures / dislocations; splint / pelvic wrap if unstable pelvis"},{"t":"Serial examinations (ED observation / inpatient)"}],"Co":[{"t":"Trauma surgery; orthopedics / neurosurgery as indicated; admit"}]},"name":"Major trauma, hemodynamically stable (primary / secondary survey, imaging)","level":"I","imp":"Major trauma, adult, stable","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen (primary survey)","sc":"مرد ۳۵ ساله پس از تصادف خودرو با درد قفسه و شکم، GCS 15، فشار 125/80 و HR 100.","why":"ABCDE، eFAST و CT بدنه."},{"id":"trauma-adult-unstable","o":{"I":[{"t":"eFAST (free fluid / pericardial / pneumothorax); CXR portable; pelvis radiograph"},{"t":"CT only if responds / stable; penetrating abdominal trauma in shock → early operative intervention (no CT)"}],"L":[{"t":"Type and crossmatch (emergency release), CBC, coagulation, fibrinogen, ABG / lactate, ionized calcium"}],"S":[{"t":"Two large-bore IV (central / IO if needed); rapid warm crystalloid 2 L then type O blood (O-negative for females of childbearing age) if no marked improvement"},{"t":"Massive transfusion protocol: PRBC : FFP 1:1 (and platelets) when > 10 units anticipated"},{"t":"Tranexamic acid IV (early administration may reduce mortality)","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Intubation by RSI with in-line stabilization if indicated (GCS < 8 / inability to protect airway); needle decompression then tube thoracostomy for tension pneumothorax; pericardiocentesis for tamponade; direct pressure on brisk external bleeding; pelvic wrap / sling; left lateral decubitus in late pregnancy"},{"t":"Correct acidosis, hypothermia and hypocalcemia; blood warmer"}],"Co":[{"t":"Immediate trauma surgery / operating room (or transfer to a facility with surgical / critical care resources); ICU"}]},"name":"Major trauma with hemorrhagic shock (resuscitation)","level":"I","imp":"Major trauma with hemorrhagic shock","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مرد ۴۰ ساله با ضربه نافذ شکم، فشار 70/40، HR 140 و رنگ‌پریده.","why":"احیا، خون O، tranexamic acid و اتاق عمل فوری."}],"ch":"156","name":"Major trauma in adults (primary and secondary survey; hemorrhagic shock)","name_fa":"ترومای عمده بزرگسال (survey اولیه و ثانویه؛ شوک هموراژیک)","cc":["trauma-major"],"keywords":"trauma, ABCDE, primary survey, secondary survey, hemorrhagic shock, eFAST, tranexamic acid, massive transfusion, tension pneumothorax, ترومای عمده, شوک هموراژیک","status":"draft","features":["راهنمای مراقبت: ارزیابی سریع، تریاژ، احیا، ارزیابی مجدد سریال، تشخیص و مداخله درمانی؛ علائم غیراختصاصی (تاکی‌کاردی، تاکی‌پنه، تغییر خفیف هوشیاری) را تا اثبات خلاف جدی بدان؛ مکانیسم آسیب بدون علائم نیز باید دنبال شود","survey اولیه (جدول 156-1): A: راه هوایی و ستون گردن: jaw thrust/chin lift، ساکشن؛ اینتوباسیون با تثبیت in-line در کاهش هوشیاری یا ناتوانی محافظت؛ راه هوایی جراحی در خونریزی/انسداد قابل‌توجه یا لارنگوسکوپی ممکن نیست؛ B: تهویه با 100% اکسیژن، سمع، بازرسی قفسه و گردن (انحراف نای، زخم باز، حرکت غیرطبیعی دیواره، crepitus)؛ سوزن‌گذاری فوری در tension pneumothorax، chest tube در hemopneumothorax؛ C: وضعیت حجم خون: رنگ پوست، پر شدن مویرگی، نبض و فشار؛ دو IV بزرگ؛ انفوزیون سریع کریستالوئید گرم؛ فشار مستقیم بر خونریزی خارجی؛ مرکزی/IO اگر محیطی ممکن نیست؛ پریکاردیوسنتز در تامپوناد؛ left lateral decubitus در حاملگی دیررس؛ D: معاینه عصبی، مردمک، قدرت، GCS، قند مویرگی؛ E: لخت کردن کامل، log-roll با تثبیت in-line، معاینه ستون توراسیک، فلانک، پشت، باسن","survey ثانویه: scalp، ثبات صورت، hemotympanum، epistaxis/هماتوم سپتوم، دندان کنده/فک، شکم، زخم نافذ، ثبات لگن (wrap)، پرینه، مئاتوس ادراری (خون)، معاینه رکتال، نبض محیطی، دفورمیتی اندام و ایمبیلیزاسیون شکستگی و دررفتگی","خونریزی تا 30% حجم کل ممکن فقط تاکی‌کاردی خفیف و کاهش pulse pressure؛ تدریجی به شوک؛ GCS 15 TBI را رد نمی‌کند؛ آسیب‌های اغلب از دست رفته: ارتوپدی؛ مری، دیافراگم و روده کوچک گاه تأخیری"],"ddx":[{"n":"Tension pneumothorax / cardiac tamponade / massive hemothorax |","cm":1},{"n":"Intra-abdominal / pelvic / retroperitoneal hemorrhage |","cm":1},{"n":"Spinal cord injury / traumatic brain injury |"}],"redflags":["GCS < 8، شوک، tension pneumothorax، تامپوناد، مکانیسم پرخطر"],"guide":"1) مدیریت پیش از رسیدن بیمار (EMS: مکانیسم، علائم حیاتی، آسیب‌ها، درمان). 2) راه هوایی: jaw thrust سپس airway دهانی/بینی (بینی در شکستگی قاعده جمجمه ممنوع)؛ اینتوباسیون در GCS < 8 و بیمار آژیته نیازمند تشخیص/درمان یا جراحی فوری؛ دو نفر (یک نفر ثبات in-line)؛ تقریباً همه با RSI؛ ترومای وسیع صورت یا ناتوانی اینتوباسیون: cricothyrotomy. 3) پس از راه هوایی: نای منحرف (tension)، crepitus، flail chest، sucking chest wound، sternum، عدم صدای تنفسی (pneumothorax ساده/tension، hemothorax ماسیو، اینتوباسیون برونش اصلی راست): tension pneumothorax فوراً سوزن‌گذاری سپس tube thoracostomy. 4) وضعیت همودینامیک: هوشیاری، رنگ پوست، نبض‌ها، HR، BP، pulse pressure؛ دو IV بزرگ و نمونه آزمایشگاه به‌ویژه type and screen؛ خط مرکزی در ناپایدار؛ tranexamic acid زودهنگام ممکن مرگ‌ومیر را کم کند. 5) ناپایدار بدون اندیکاسیون واضح جراحی: پس از 2 L کریستالوئید گرم؛ بهبود نیافت: PRBC نوع O (O-منفی برای زن سن باروری)؛ eFAST بلافاصله پس از survey اولیه؛ پایدار: CT شکم و لگن با کنتراست IV؛ نافذ شکم با شوک: جراحی زودهنگام. 6) کوآگولوپاتی ترومایی: > 10 واحد PRBC: PRBC:FFP 1:1؛ اسیدوز و هیپوترمی اصلاح شوند. 7) معاینه عصبی مختصر؛ قند مویرگی؛ فرض TBI قابل‌توجه؛ GCS 3 تا 8: هر اقدام غیرضروری را تا CT سر به تأخیر بینداز؛ کاپنوگرافی مداوم در اینتوبه. 8) log-roll با ثبات in-line؛ لمس spinous process؛ معاینه رکتال. 9) آسیب مری، دیافراگم و روده کوچک ممکن تشخیص داده نشود: تصویربرداری بیشتر و مشاهده؛ بیشتر از دست رفته: ارتوپدی. 10) ناپایداری همراه خونریزی ادامه‌دار: اتاق عمل یا انتقال؛ معاینات سریال.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 156: Trauma in Adults, pp. 865–868"},"major-trauma-peds":{"id":"major-trauma-peds","variants":[{"id":"trauma-peds-resuscitation","o":{"I":[{"t":"CXR portable (essential for chest trauma; CT chest rarely changes management); pelvis radiograph; plain spine films as indicated; eFAST (limited role); noncontrast CT head (TBI) and cervical spine CT when indicated; CT abdomen / pelvis if suspicious mechanism, tenderness, seatbelt sign, distention, vomiting"}],"L":[{"t":"Type and screen / crossmatch, CBC, BMP, PT/INR, lactate, glucose (capillary), ABG; urinalysis; toxicology as indicated"}],"S":[{"t":"Two proximal IVs (or early intraosseous); crystalloid boluses 20 mL/kg; if no response after two boluses: 10 mL/kg packed red blood cells; massive transfusion protocol if large-volume resuscitation anticipated","fl":[{"k":"ci","v":"permissive hypotension not evidence-based in children"}]},{"t":"Fentanyl 1 µg/kg or morphine 0.05–0.1 mg/kg for pain"}],"T":[{"t":"Airway: jaw thrust, suction, sniffing position (towel under shoulders); orotracheal intubation with in-line cervical stabilization by RSI; ETT size = 4 + (age/4) (½ smaller if cuffed, preferred); limit bag-mask ventilation to avoid gastric insufflation"},{"t":"Estimated hypotension SBP < 70 + (2 × age); modified pediatric GCS; maintain normothermia (expose but warm)"}],"Co":[{"t":"Pediatric trauma center transfer / pediatric surgery / neurosurgery; admit (ICH, spine, significant chest or abdominal trauma, burns); consider child abuse"}]},"name":"Pediatric major trauma — resuscitation (airway, IV/IO, fluids)","level":"I","imp":"Major trauma, pediatric","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen (non-rebreather) — pediatric override applies","sc":"کودک ۶ ساله 20 kg پس از تصادف با HR 150، فشار 75/40، پر شدن مویرگی طولانی و GCS 12.","why":"IV/IO، 20 mL/kg، خون و CT؛ تثبیت و انتقال به مرکز کودک."},{"id":"trauma-peds-tbi-severe","o":{"I":[{"t":"Noncontrast head CT (after stabilization; before nonessential procedures); cervical spine imaging as indicated; transcranial Doppler may help in infants with open fontanelles"}],"L":[{"t":"Glucose (capillary), BMP (Na), CBC, PT/INR, blood gas; keep glucose normal"}],"S":[{"t":"3% hypertonic saline 5 mL/kg bolus over 10 min then infusion 0.1 mL/kg/h to keep Na 155–165 mEq/L, OR mannitol 0.5–1 g/kg if normotensive","fl":[{"k":"ci","v":"mannitol only if normotensive"}]},{"t":"Midazolam / fentanyl sedation and analgesia; consider paralytics once neuro exam complete (GCS before paralytics)"},{"t":"Seizure prophylaxis optional (witnessed posttraumatic seizure, intracranial blood): phenytoin 20 mg/kg (or fosphenytoin 20 PE/kg) or levetiracetam 10–20 mg/kg (max 500 mg/dose) for first week"},{"t":"Transfuse PRBC if Hb < 7 g/dL; maintain SBP > 70 + (2 × age)","fl":[{"k":"ci","v":"no permissive hypotension; no prophylactic hyperventilation"}]}],"T":[{"t":"Intubate for GCS < 8; oxygen saturation > 90%, PCO2 35–40 mmHg; head of bed 30°; cervical spine precautions; core temperature 36–38°C (avoid hyperthermia; hypothermia not recommended); CPP 40–65 mmHg; ICP ≤ 20 mmHg"},{"t":"Impending herniation: maintain PaCO2 35–40, optimize blood pressure with IV fluids, elevate head of bed 20–30°"}],"Co":[{"t":"Neurosurgery (ICP monitoring, hematoma evacuation, CSF shunt for refractory intracranial hypertension) / pediatric trauma center; PICU"}]},"name":"Severe pediatric traumatic brain injury / impending herniation","level":"I","imp":"Severe pediatric traumatic brain injury","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate SpO2 > 90% (PCO2 35–40 mmHg)","sc":"کودک ۴ ساله پس از سقوط از ارتفاع با GCS 6، مردمک نامساوی و اتساع فونتانل.","why":"اینتوباسیون، CT، ICP management؛ بدون hyperventilation پروفیلاکتیک."}],"ch":"157","name":"Major trauma in children (airway, shock, TBI, thoracoabdominal injury)","name_fa":"ترومای عمده کودک","cc":["trauma-major","pediatric-other"],"keywords":"pediatric trauma, modified pediatric GCS, Broselow, intraosseous, TBI children, pulmonary contusion, abdominal trauma CT rules, ترومای کودک","status":"draft","features":["تروما شایع‌ترین علت مرگ کودک > 1 سال؛ تفاوت‌های آناتومی و فیزیولوژی؛ سر شایع‌ترین آسیب کشنده؛ تصادف خودرو شایع‌ترین مکانیسم","راه هوایی: occiput بزرگ، زبان بزرگ، حنجره بالاتر؛ تنفس: کودک سریع‌تر desaturate می‌شود؛ گردش: تاکی‌کاردی، تغییر وضعیت ذهنی و پرفیوژن غیرطبیعی زودهنگام؛ هیپوتانسیون معمولاً حادثه نهایی؛ فشار سیستولیک نرمال 1 تا 10 سال: 90 + (2 × سن) mmHg؛ هیپوتانسیون: < 70 + (2 × سن)","GCS اصلاح‌شده کودک (جدول 157-1): coos/babbles = 5، irritable cry = 4، cries to pain = 3، moans to pain = 2، بدون پاسخ = 1؛ مردمک، تون و قدرت؛ سطح بدن/جرم بیشتر ← خطر هیپوترمی","سر: شیرخوار/نوزاد بیشترین خطر آسیب داخل‌جمجمه؛ شکستگی parietal/occipital اغلب با خونریزی؛ CT بدون کنتراست؛ scalp نوزاد: خونریزی قابل‌توجه و شوک؛ ستون: آسیب نخاع اغلب بدون شکستگی (لیگامان الاستیک)؛ تروما چندسیستمی و سر: ایمبیلیزاسیون گردن و تصویربرداری؛ رادیوگرافی ساده مفید","قفسه: CXR ضروری؛ CT تغییر مدیریت نمی‌دهد؛ کوفتگی ریه شایع‌ترین؛ شکستگی دنده کمتر و مکانیسم شدید","شکم و ادراری-تناسلی: اندیکاسیون CT: مکانیسم مشکوک، حساسیت، seatbelt sign، اتساع و استفراغ؛ پیش‌بینی خطر بسیار کم: بدون تروما دیواره شکم/seat belt یا GCS < 14؛ بدون حساسیت شکم؛ بدون تروما دیواره قفسه و بدون درد شکم/کاهش صداهای روده/استفراغ؛ شکستگی لگن (به‌ویژه حلقه قدامی): آسیب مجرا یا مثانه؛ نقش سونوگرافی در پایدار معلوم نیست"],"ddx":[{"n":"Child abuse (non-accidental trauma) |","cm":1},{"n":"Tension pneumothorax / tamponade / hemorrhage |","cm":1},{"n":"Spinal cord injury without radiographic abnormality |"}],"redflags":["GCS < 8، هیپوتانسیون، علائم herniation، مکانیسم پرخطر، شک سوءاستفاده"],"guide":"1) مانورهای پایه راه هوایی: jaw thrust، ساکشن دهانی، sniffing position (حوله زیر شانه‌ها)؛ 2) اینتوباسیون: اندازه لوله = 4 + (سن/4)، ½ کمتر برای cuffed (ترجیحاً)؛ ثبات in-line همیشه؛ RSI ایمن‌ترین؛ محدود کردن فشار مثبت قبل از اینتوباسیون. 3) دسترسی عروقی: دو IV پروگزیمال در بحرانی؛ IO زود؛ مرکزی: ورید فمورال؛ مایع: 20 mL/kg بولوس کریستالوئید؛ بدون پاسخ به دو بولوس: 10 mL/kg PRBC؛ permissive hypotension در کودک مبتنی بر شواهد نیست و ممکن مضر؛ massive transfusion protocol اگر حجم بالا. 4) درد: fentanyl 1 µg/kg یا morphine 0.05 تا 0.1 mg/kg. 5) نشانه‌های herniation: PaCO2 35 تا 40 mmHg، بهینه‌سازی فشار با مایع IV، بالا بردن سر 20 تا 30°. جدول 157-2 TBI شدید: ستون گردن: احتیاط؛ راه هوایی: اینتوباسیون برای GCS < 8؛ SpO2 > 90% و PCO2 35 تا 40؛ SBP > 70 + (2 × سن)؛ CPP 40 تا 65؛ بدون hyperventilation پروفیلاکتیک و بدون permissive hypotension؛ ICP ≤ 20؛ مشاوره نوروسرجری؛ GCS قبل از شل‌کننده؛ midazolam و fentanyl؛ CT سر بدون کنتراست و CT گردن؛ قند نرمال؛ ICP بالا: بالا بردن سر 30°، سالین هیپرتونیک 3% بولوس 5 mL/kg طی 10 دقیقه سپس 0.1 mL/kg/h برای Na 155 تا 165 mEq/L یا mannitol 0.5 تا 1 g/kg اگر نورموتانسیو؛ دما 36 تا 38°C (هیپوترمی در کودک توصیه نمی‌شود)؛ پیشگیری تشنج اختیاری: phenytoin 20 mg/kg (یا fosphenytoin 20 PE/kg) یا levetiracetam 10 تا 20 mg/kg (حداکثر 500 mg/dose) هفته اول؛ ترانسفیوژن برای Hb < 7؛ ICP monitoring، تخلیه هماتوم یا shunt در ICP مقاوم. 6) بستری: خونریزی داخل‌جمجمه، ترومای ستون، قفسه مهم، شکم با آسیب عضو، سوختگی، آسیب نگران‌کننده؛ انتقال به مرکز تروما کودک (جدول 157-3): پرتاب از خودرو، سقوط از ارتفاع قابل‌توجه، تصادف با extrication طولانی یا مرگ سرنشین دیگر؛ تروما چندگانه شدید، > 3 شکستگی استخوان بلند، شکستگی ستون/آسیب نخاع، قطع عضو، ترومای شدید سر/صورت، تروما نافذ سر/قفسه/شکم.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 157: Trauma in Children, pp. 869–872"},"trauma-elderly":{"id":"trauma-elderly","variants":[{"id":"trauma-elderly-main","o":{"I":[{"t":"Noncontrast head CT (warfarin / anticoagulant: even minor head injury); CT cervical spine (preferred; C1 / C2 fractures); CXR portable; CT chest / abdomen / pelvis with IV contrast if stable (hydration and renal function check first); FAST (unstable); pelvis radiograph / CT pelvis if tenderness and negative plain films; hip / extremity radiographs"}],"L":[{"t":"Lactate and base deficit (serial), ABG, CBC, BMP / creatinine, type and screen / crossmatch, PT/INR, aPTT, troponin, glucose, ECG (syncope / dysrhythmia as cause of fall), urinalysis"}],"S":[{"t":"Crystalloid judiciously (diminished cardiac compliance — volume overload risk) ; earlier and more liberal PRBC transfusion to enhance oxygen delivery","fl":[{"k":"ci","v":"avoid over-resuscitation / heart failure"}]},{"t":"Reverse anticoagulation rapidly in warfarin with intracranial bleeding on CT (vitamin K IV, 4-factor PCC / FFP); reasonable to reverse aspirin / clopidogrel / heparin in diagnosed ICH"},{"t":"Analgesia titrated for rib fractures (consider regional block)","fl":[{"k":"ci","v":"NSAIDs with renal disease / anticoagulation"}]}],"T":[{"t":"Early intubation and mechanical ventilation if severe injury, RR > 40, PaO2 < 60 mmHg or PaCO2 > 50 mmHg; cervical immobilization until assessed; frequent vital signs (\"normal\" vitals not reassuring; β-blocker masking)"},{"t":"Search for cause of fall (syncope: dysrhythmia, hypoglycemia, anemia, hypoxia); screen for elder abuse / neglect"}],"Co":[{"t":"Trauma surgery; orthopedics (hip / pelvis / long bone — early consultation); neurosurgery if ICH; ICU for polytrauma, chest wall injury, abnormal vitals or occult hypoperfusion; admit rib fractures for pain control and pulmonary toilet"}]},"name":"Elderly trauma (fall / MVC) — resuscitation, occult shock, anticoagulation","level":"I","imp":"Trauma in the elderly","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate to SpO2 ≥ 94%","sc":"زن ۸۲ ساله مصرف‌کننده warfarin پس از سقوط با ضربه به سر، درد قفسه (شکستگی دنده)، HR 95 و فشار 115/70.","why":"CT سر/ستون/قفسه، لاکتات و ICU؛ ضدانعقاد را برگردان."}],"ch":"158","name":"Trauma in the elderly","name_fa":"تروما در سالمند","cc":["trauma-major","head-injury"],"keywords":"geriatric trauma, fall elderly, anticoagulated head injury, rib fractures elderly, hip fracture, C1 C2 fracture, subdural hematoma, تروما سالمند, سقوط سالمند","status":"draft","features":["سقوط شایع‌ترین علت آسیب کشنده و غیرکشنده در ≥ 65 سال؛ سنکوپ (دیسریتمی، venous pooling، اختلال اتونوم، هیپوکسی، کم‌خونی، هیپوگلیسمی)؛ تصادف خودرو دومین علت آسیب و علت اول مرگ؛ عابر پیاده سالمند مرگ بیشتر؛ آسیب عمدی و ناشی از غفلت را در نظر بگیر","بیمار را هم طبی و هم تروما ارزیابی کن؛ شرح حال دقیق (خانواده، پرونده، پزشک)؛ داروها: قلبی، دیورتیک، روان‌گردان و ضدانعقاد؛ علت سقوط ممکن علت طبی جدی را نشان دهد","علائم حیاتی «نرمال» اطمینان‌بخش نیست: تاکی‌کاردی ممکن وجود نداشته یا کند (β-blocker)؛ فشار خون گمراه‌کننده (HTN زمینه‌ای): آستانه هیپوتانسیون بالاتر؛ تروما بلانت ≥ 65: مرگ‌ومیر با SBP < 110 و HR > 90 افزایش می‌یابد","راه هوایی: دندان مصنوعی، آرتریت گردن/TMJ؛ survey ثانویه کامل (آسیب‌های «جزئی» تجمعی)؛ بیمار به‌ظاهر پایدار ممکن ناگهانی بدتر شود","سر: تغییر وضعیت ذهنی را صرفاً به دمانس نسبت نده؛ epidural کمتر؛ subdural و intraparenchymal بیشتر؛ ICH در بیماران ضدانعقاد با ضربه بلانت بدون/با علائم حداقل 7 تا 14%؛ CT سر بدون کنتراست در مصرف warfarin با هر مکانیسم نگران‌کننده حتی سر خفیف","ستون گردن: شکستگی C1 و C2 بیشتر؛ ایمبیلیزاسیون تا ارزیابی؛ CT روش اولیه ترجیحی (دژنراسیون رادیوگرافی را تفسیر دشوار می‌کند)","قفسه: شکستگی دنده بیشتر (استئوپروز)؛ درد + ذخیره فیزیولوژیک کم ← عوارض تنفسی؛ hemopneumothorax، کوفتگی ریه، flail chest و کوفتگی قلب سریعاً دکمپانسه","شکم: معاینه غیرقابل اتکا؛ FAST برای هموپریتوان در ناپایدار (جایگزین DPL)؛ CT با کنتراست در پایدار؛ هیدراتاسیون و کراتینین پایه قبل از کنتراست","ارتوپدی: شکستگی هیپ (بین‌تروکانتریک شایع‌ترین، transcervical، subcapital، subtrochanteric)؛ لگن و استخوان بلند ممکن تنها علت هیپوولمی؛ مشاوره ارتوپدی زودهنگام؛ CT لگن اگر رادیوگرافی منفی و حساسیت؛ استخوان بلند (فمور، تیبیا، هومروس): rodding داخل‌مدولاری ← تحرک زودتر؛ Colles و شکستگی هومروس پروگزیمال/surgical neck با سقوط روی دست یا آرنج"],"ddx":[{"n":"Intracranial hemorrhage (SDH) on anticoagulation |","cm":1},{"n":"Occult shock / hip or pelvic fracture hemorrhage |","cm":1},{"n":"Syncope / medical cause of fall / elder abuse |"}],"redflags":["SBP < 110 و HR > 90، ضدانعقاد، GCS کاهش‌یافته، شکستگی C1/C2، دنده متعدد"],"guide":"survey اولیه و ثانویه سریع. 1) هدف اصلی: رسانش اکسیژن کافی؛ اینتوباسیون زودهنگام در آسیب شدید، RR > 40، PaO2 < 60 یا PaCO2 > 50. 2) احیای بیش‌ازحد مثل ناکافی خطرناک؛ کریستالوئید با احتیاط؛ استفاده زودتر و آزادتر از PRBC. 3) base deficit و lactate شاخص اولیه شوک و سریال. 4) پایش تهاجمی زودهنگام ممکن (عدم قطعیت بهترین رویکرد): تصویربرداری لازم برای آسیب تهدیدکننده (CT سر، ستون، قفسه، شکم، لگن) سپس ICU برای بهینه‌سازی همودینامیک و بعد تصویربرداری/مداخله غیرضروری. 5) برگرداندن سریع ضدانعقاد در warfarin با خونریزی داخل‌جمجمه‌ای؛ برگرداندن سایر (aspirin، clopidogrel، heparin) منطقی در ICH تشخیص‌داده‌شده. 6) آستانه پایین بستری با شکستگی دنده تا کنترل درد و pulmonary toilet. 7) polytrauma، قفسه مهم، علائم حیاتی غیرطبیعی یا hypoperfusion آشکار/پنهان: ICU.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 158: Trauma in the Elderly, pp. 873–876"},"trauma-pregnancy":{"id":"trauma-pregnancy","variants":[{"id":"trauma-pregnancy-major","o":{"I":[{"t":"eFAST / bedside ultrasonography (abdomen, FHR, placental location, fetal activity, amniotic fluid) — pelvic US before speculum / vaginal exam; CT / radiographs per usual trauma principles (do not withhold; fetal harm negligible < 5 rad; shield pelvis when possible, limit CT cuts)"},{"t":"Cardiotocodynamometry / external fetal monitoring ≥ 4–6 h (beyond 20 weeks)"}],"L":[{"t":"CBC, chemistries, blood type and Rh, coagulation with fibrin split products and fibrinogen (DIC), type and crossmatch, Kleihauer–Betke test (or Apt test), pH of vaginal fluid / ferning (amniotic rupture), urinalysis, toxicology, ABG"}],"S":[{"t":"Supplemental oxygen and crystalloid at rates 50% above non-pregnant patients","fl":[{"k":"ci","v":"avoid vasopressors if possible (uterine perfusion)"}]},{"t":"Rho(D) immune globulin for all Rh-negative pregnant patients (dose per Kleihauer–Betke result)","fl":[{"k":"hi","v":""}]},{"t":"Tocolytics only in consultation with obstetrician (side effects: maternal and fetal tachycardia)"},{"t":"Tetanus prophylaxis when indicated"}],"T":[{"t":"Primary / secondary survey; beyond 20 weeks: wedge under right hip tilting patient 30° to left (or left lateral decubitus) to avoid supine hypotension syndrome; sterile pelvic examination after US"},{"t":"Indications for emergent laparotomy same as non-pregnant; emergent cesarean for fetal distress beyond viable gestational age (consider perimortem cesarean in maternal arrest)"},{"t":"Screen for intimate partner violence; instruct discharged patients to return for abdominal pain / cramps, vaginal bleeding, fluid leakage, decreased fetal movement"}],"Co":[{"t":"Obstetrics (early) and trauma surgery; observe or admit ≥ 20 weeks for minimum 4–6 h tocodynamometric monitoring; ICU if unstable"}]},"name":"Major trauma in pregnancy (resuscitation, fetal assessment)","level":"I","imp":"Major trauma in pregnancy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen","sc":"زن ۲۸ ساله باردار 30 هفته پس از تصادف با درد شکم، خونریزی واژینال خفیف و انقباضات؛ فشار 95/55 و HR 115.","why":"تثبیت مادر، پایش جنین و مشاوره مامایی/جراحی؛ ایزوایمونوگلوبولین."},{"id":"trauma-pregnancy-minor","o":{"I":[{"t":"Bedside ultrasonography (FHR, placenta, fluid); external fetal monitoring ≥ 4–6 h"}],"L":[{"t":"Blood type and Rh; Kleihauer–Betke test; CBC"}],"S":[{"t":"Rho(D) immune globulin if Rh-negative","fl":[{"k":"hi","v":""}]},{"t":"Tetanus prophylaxis if indicated"}],"T":[{"t":"Left lateral position; observation with tocodynamometry"}],"Co":[{"t":"Obstetrics consultation; discharge if monitoring normal with return precautions (abdominal pain / cramps, vaginal bleeding, leakage of fluid, decreased fetal activity)"}]},"name":"Minor blunt trauma in pregnancy (≥ 20 weeks; fetal monitoring)","level":"II","imp":"Minor trauma in pregnancy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زن ۲۵ ساله باردار 24 هفته پس از سقوط خفیف با درد کم شکم؛ علائم حیاتی طبیعی.","why":"مانیتور 4 تا 6 ساعت و Rh/KB؛ ترخیص با دستور بازگشت."}],"ch":"159","name":"Trauma in pregnancy","name_fa":"تروما در بارداری","cc":["trauma-major","pregnancy"],"keywords":"pregnancy trauma, placental abruption, Kleihauer-Betke, Rh immunoglobulin, supine hypotension, fetal monitoring, perimortem cesarean, تروما در بارداری, جدا شدن جفت","status":"draft","features":["تروما علت اول عوارض و مرگ غیرمامایی در باردار؛ MVC، سقوط و خشونت خانگی؛ بقا و سلامت جنین وابسته به تثبیت مادر","فیزیولوژی: HR 10 تا 20 bpm در سه‌ماهه دوم؛ فشار سیستولیک/دیاستولیک 10 تا 15 mmHg کاهش؛ حجم خون تا 45% بیشتر ولی توده RBC کمتر ← کم‌خونی فیزیولوژیک؛ تا 30 تا 35% حجم خون را از دست می‌دهد قبل از شوک؛ بالا رفتن دیافراگم، کاهش RV و FRC، افزایش tidal volume (هیپرونتیلاسیون و آلکالوز تنفسی با pH نرمال)؛ تأخیر تخلیه معده (خطر آسپیراسیون)","آسیب: طحال شایع‌ترین علت خونریزی شکم؛ پس از هفته 12 رحم از لگن خارج و در هفته 20 به ناف؛ جریان رحم بیشتر ← خونریزی مادری شدید؛ «supine hypotension syndrome» (فشار رحم روی IVC)؛ روده کوچک به سمت بالا (آسیب نافذ شکم فوقانی)؛ مثانه سه‌ماهه سوم در شکم","آسیب جنین: بیشتر سه‌ماهه سوم، همراه شکستگی لگن یا ترومای نافذ؛ پارگی رحم نادر ولی مرگ‌ومیر بالای جنین؛ شایع‌تر: تحریک‌پذیری رحم، زایمان زودرس، جدا شدن جفت: درد شکم، خونریزی واژینال و انقباضات؛ خونریزی جنین-مادر > 30% ← ایزوایمونیزاسیون Rh"],"ddx":[{"n":"Placental abruption / uterine rupture |","cm":1},{"n":"Splenic / hepatic injury / hemorrhagic shock |","cm":1},{"n":"Supine hypotension syndrome / amniotic fluid embolism |"}],"redflags":["خونریزی واژینال، درد شکم، انقباضات، کاهش حرکات جنین، FHR غیرطبیعی"],"guide":"بقا و ثبات مادر بهترین شانس جنین؛ هیچ مداخله حیاتی یا تشخیصی نباید به‌علت نگرانی جنین به تأخیر افتد. ترتیب احیای تروما تغییر نمی‌کند؛ توجه به شکم باردار (آسیب، حساسیت، انقباض). شک تروما شکم/لگن: معاینه استریل لگن (ترومای ژنیتال، خونریزی واژینال، پارگی پرده‌ها) پس از سونوگرافی لگن برای محل جفت؛ مایع واژینال با pH 7 و «ferning» ← پارگی آمنیوتیک. آزمایش: CBC، شیمی، گروه خون، Rh، انعقاد با FDP و فیبرینوژن (DIC)؛ Apt یا Kleihauer–Betke. پرتو: عارضه جنینی ناچیز زیر 5 rad (بیشتر از رادیوگرافی ساده)؛ کاهش تعداد برش CT و محافظ؛ سونوگرافی بالین بسیار حساس، اختصاصی و بدون پرتو (FHR، سن حاملگی، فعالیت/مرگ جنین، محل جفت، حجم مایع آمنیوتیک)؛ DPL با روش open supraumbilical اگر لازم. FHR نرمال 120 تا 160؛ برادیکاردی جنین ← هیپوکسی (هیپوتانسیون مادر، اختلال تنفسی، abruption)؛ تاکی‌کاردی ← هیپوکسی یا هیپوولمی؛ تروما بلانت شکم: مانیتورینگ خارجی جنین ≥ 4 تا 6 ساعت در همه بالای هفته 20؛ تاکی‌کاردی جنین، نبود تغییرپذیری یا late decelerations ← distress و ممکن سزارین اورژانس بالای سن زنده‌مانی. 1) احیای تهاجمی مادر = بهترین احیای جنین. 2) اکسیژن و کریستالوئید 50% بیشتر از غیرباردار؛ بالای هفته 20 در supine: wedge زیر هیپ راست، 30° به چپ، یا left lateral decubitus. 3) از وازوپرسور در صورت امکان پرهیز. 4) کزاز. 5) Rho(D) immunoglobulin برای Rh-منفی. 6) cardiotocodynamometry زودهنگام. 7) توکولیتیک فقط با مشورت مامایی. 8) اندیکاسیون لاپاراتومی مثل غیرباردار. 9) بالای 20 هفته: مشاهده یا بستری حداقل 4 تا 6 ساعت. 10) غربال خشونت شریک. 11) دستور بازگشت فوری: درد شکم/گرفتگی، خونریزی واژینال، نشت مایع، کاهش حرکات جنین.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 159: Trauma in Pregnancy, pp. 877–879"},"head-trauma-mild":{"id":"head-trauma-mild","variants":[{"id":"head-trauma-mild-ctrule","o":{"I":[{"t":"Noncontrast head CT if any rule criterion present (Canadian CT Head Rule / New Orleans / ACEP); cervical spine imaging if altered mental status, neck pain, intoxication, neurologic deficit, distracting injury, or serious mechanism (NEXUS / Canadian C-spine rule)"}],"L":[{"t":"Glucose; coagulation (PT/INR) if anticoagulant use; blood alcohol / toxicology if intoxication"}],"S":[{"t":"Analgesia (acetaminophen; avoid NSAIDs / sedatives until CT); antiemetic"}],"T":[{"t":"Serial neurologic examinations / observation; head injury discharge instructions; companion able to observe for ≥ 24 h"}],"Co":[{"t":"Discharge if GCS 15 maintained, normal serial exams and normal CT; abnormal CT: neurosurgery consultation and admission; GCS 14 with normal CT: observe in ED until GCS 15 and symptom-free"}]},"name":"Mild head trauma — CT per rule, observation / discharge","level":"II","imp":"Mild traumatic brain injury","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله پس از سقوط از دوچرخه با ضربه به سر، LOC کوتاه، سردرد و دو بار استفراغ؛ GCS 15.","why":"CT طبق Canadian/New Orleans؛ مشاهده و ترخیص."}],"ch":"160","name":"Mild traumatic brain injury (GCS ≥ 14) — CT decision rules and disposition","name_fa":"ضربه خفیف سر (GCS ≥ 14) — قوانین CT و ترخیص","cc":["head-injury","headache"],"keywords":"mild TBI, concussion, Canadian CT head rule, New Orleans criteria, minor head injury, CT head, observation, ضربه خفیف سر, کانکاشن","status":"draft","features":["TBI: اختلال عملکرد مغز پس از نیروی مستقیم یا غیرمستقیم (شتاب/کاهش شتاب)؛ خفیف: GCS ≥ 14: بدون علامت (فقط سابقه ضربه) یا گیج و فراموشی؛ ممکن از دست رفتن گذرای هوشیاری و سردرد منتشر، تهوع و استفراغ","پرخطر در زیرگروه: شکستگی جمجمه، تورم subgaleal بزرگ، یافته عصبی کانونی، کوآگولوپاتی، سن > 60، مسمومیت دارو/الکل","GCS (جدول 160-1): چشم: 4 تا 1؛ کلامی: 5 تا 1؛ حرکتی: 6 تا 1؛ 3 تا 15؛ اینتوبه: کلامی 1 و «T»","قوانین تصمیم CT (جدول 160-2): New Orleans (GCS 15): سردرد، استفراغ، سن > 60، مسمومیت، آمنزی آنتروگرید پایدار، شواهد تروما بالای ترقوه؛ حساسیت 100% برای ضایعه داخل‌جمجمه‌ای (ویژگی 5%)؛ Canadian CT Head Rule (GCS 13 تا 15): GCS < 15 در 2 ساعت، شکستگی باز/فرورفته مشکوک، سن ≥ 65، بیش از یک استفراغ، آمنزی رتروگرید > 30 دقیقه، مکانیسم خطرناک (سقوط > 3 ft یا عابر)، تشنج، علامت شکستگی قاعده؛ 83% حساس، 38% اختصاصی برای ضایعه؛ 100% برای نیاز جراحی؛ وجود هر یک ← CT","ACEP (جدول 160-3): GCS < 15 هنگام ارزیابی: CT؛ TBI خفیف با/بدون LOC: اگر هر یک: GCS < 15، یافته عصبی کانونی، استفراغ > 2 بار، سردرد متوسط تا شدید، سن > 65، شکستگی قاعده، کوآگولوپاتی، مکانیسم خطرناک (سقوط > 4 ft)؛ TBI خفیف با LOC یا آمنزی: مسمومیت دارو/الکل، شواهد بالای ترقوه، آمنزی پایدار، تشنج پس از ضربه","حدود 8% TBI شدید با شکستگی گردن؛ تصویربرداری گردن برای هر تروما با تغییر وضعیت ذهنی، درد گردن، مسمومیت، نقص عصبی، آسیب حواس‌پرتی شدید یا مکانیسم جدی"],"ddx":[{"n":"Intracranial hemorrhage (SDH / EDH / SAH) |","cm":1},{"n":"Cervical spine injury |","cm":1},{"n":"Concussion / intoxication / seizure / syncope as cause of fall |"}],"redflags":["GCS < 15، استفراغ مکرر، سن > 65، ضدانعقاد، نقص کانونی، شکستگی قاعده"],"guide":"ترخیص: GCS 15 ثابت در طول مشاهده، معاینه عصبی سریال نرمال و CT نرمال؛ CT غیرطبیعی: مشاوره نوروسرجری و بستری. GCS اولیه 14 با CT نرمال: مشاهده در ED؛ اگر GCS به 15 رسید و بدون علامت و سالم عصبی پس از معاینات سریال: ترخیص با همراه معتبر برای مراقبت ≥ 24 ساعت و دستورالعمل کامل.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 160: Head Trauma, pp. 880–885"},"head-trauma-moderate-severe":{"id":"head-trauma-moderate-severe","variants":[{"id":"head-trauma-moderate","o":{"I":[{"t":"Noncontrast head CT STAT (neurosurgical lesions); cervical spine imaging (≈ 8% of severe TBI have C-spine fracture); CXR portable; other trauma imaging per Chapter 156"}],"L":[{"t":"Type and crossmatch, CBC, BMP, arterial blood gas, coagulation studies, directed toxicology / ethanol, glucose"}],"S":[{"t":"Crystalloid IV to MAP ≥ 80 mmHg; vasopressors if aggressive fluid resuscitation ineffective","fl":[{"k":"ci","v":"avoid hypotension — increases mortality"}]},{"t":"Reverse coagulopathy if present (vitamin K / FFP / PCC)"},{"t":"Analgesia and adequate sedation (avoid over-sedation obscuring exam)"}],"T":[{"t":"Oxygen, cardiac monitoring, two IV lines; head of bed 30° if not hypotensive; serial GCS / pupils; cervical collar"},{"t":"Seizure prophylaxis controversial (with neurosurgery)"}],"Co":[{"t":"Neurosurgery (immediate after CT shows intracranial injury); ICU / step-down; trauma surgery"}]},"name":"Moderate TBI (GCS 9–13) / abnormal CT","level":"I","imp":"Moderate traumatic brain injury","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate to SpO2 ≥ 94% (avoid hypoxemia)","sc":"مرد ۴۵ ساله پس از ضربه با GCS 11، گیجی و استفراغ؛ CT: هماتوم ساب‌دورال حاد.","why":"CT، MAP 80، نوروسرجری و ICU."},{"id":"head-trauma-severe-herniation","o":{"I":[{"t":"Noncontrast head CT as soon as stabilized (before nonessential procedures); CT cervical spine; CXR portable"}],"L":[{"t":"Type and crossmatch, CBC, BMP (Na, osmolality), arterial blood gas, coagulation studies, toxicology, glucose; continuous capnography if intubated"}],"S":[{"t":"Mannitol 0.25–1.0 g/kg IV repetitive boluses if not hypotensive; if hypotensive or inadequately resuscitated: 3% hypertonic saline 250 mL IV over 30 min","fl":[{"k":"hi","v":""}]},{"t":"Crystalloid to MAP 80 mmHg then vasopressors if needed"},{"t":"Lorazepam IV and fosphenytoin 18–20 PE/kg IV loading for seizures"},{"t":"Prophylactic antibiotics for basilar skull fracture / penetrating injury: ceftriaxone 2 g IV and vancomycin 1 g IV"}],"T":[{"t":"Rapid sequence intubation (cervical immobilization, adequate sedation / induction agent); head of bed 30°; adequate sedation; maintain oxygenation; avoid prophylactic hyperventilation (temporary PCO2 30–35 mmHg only as last resort for herniation)"},{"t":"Emergency trephination (burr holes) if impending herniation and all other methods failed (CT first to localize)"}],"Co":[{"t":"Immediate neurosurgery; neurosurgical ICU admission"}]},"name":"Severe TBI (GCS ≤ 8) with signs of increased ICP / impending herniation","level":"I","imp":"Severe traumatic brain injury, increased ICP","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen then titrate (avoid hypoxemia)","sc":"مرد ۳۰ ساله پس از ضربه با GCS 6، مردمک راست دیلاته و ثابت، پوسچرینگ و فشار 100/60.","why":"RSI، MAP 80، مانیتول/سالین هیپرتونیک و نوروسرجری فوری."}],"ch":"160","name":"Moderate to severe traumatic brain injury (GCS ≤ 13) and intracranial injuries","name_fa":"ضربه متوسط تا شدید سر (GCS ≤ 13) و آسیب‌های داخل‌جمجمه‌ای","cc":["head-injury","altered-mental-status"],"keywords":"severe TBI, epidural hematoma, subdural hematoma, cerebral contusion, traumatic subarachnoid hemorrhage, herniation, mannitol, hypertonic saline, trephination, basilar skull fracture, TBI شدید, هماتوم ساب دورال, اپی دورال","status":"draft","features":["متوسط: GCS 9 تا 13: 40% ناهنجاری CT و 8% نیاز مداخله نوروسرجری؛ شدید: GCS < 9: مرگ‌ومیر تا 40%؛ اولویت: پیشگیری از آسیب ثانویه مغز، شناسایی آسیب‌های تهدیدکننده دیگر و ضایعات قابل جراحی","شرح حال پیش‌بیمارستانی: مکانیسم، زمان، طول بیهوشی، وضعیت ذهنی اولیه، تشنج، استفراغ؛ داروها (ضدانعقاد) و الکل/مواد؛ معاینه عصبی دقیق: GCS، مردمک (اندازه، واکنش، anisocoria)، اعصاب کرانیال، حرکتی و حسی، پوسچرینگ decorticate / decerebrate","شکستگی جمجمه: depressed (باز/بسته)؛ قاعده (معمولاً بخش petrous استخوان تمپورال): hemotympanum، CSF otorrhea/rhinorrhea، raccoon eyes، Battle sign","کوفتگی مغز و ICH: ناحیه frontal pole، subfrontal و تمپورال؛ زیر محل ضربه یا contrecoup؛ هموراژیک با ادم؛ گیجی، obtundation یا کما؛ نقص کانونی","SAH تروماتیک: شایع‌ترین ناهنجاری CT در TBI متوسط/شدید؛ ممکن CT < 6 ساعت از دست بدهد","epidural: خون بین جدار داخلی جمجمه و دورا؛ شکستگی با پارگی شریان مننژیال میانی؛ «lucid interval»؛ مردمک ثابت و دیلاته سمت ضایعه + همی‌پارزی مقابل (دیررس)؛ فتق ظرف ساعت‌ها؛ CT biconvex","subdural: خون وریدی بین دورا و عنکبوتیه؛ پارگی bridging veins؛ آتروفی مغز (الکلی، سالمند) مستعد؛ حاد ≤ 14 روز (بیشتر علامت‌دار ظرف 24 ساعت)؛ مزمن > 2 هفته؛ CT: هلالی هایپردانس و عبور از suture","herniation: transtentorial (uncal): فشار روی عصب سوم ← مردمک ثابت و دیلاته همان سمت؛ فشار peduncle ← فلج مقابل؛ false localizing sign؛ central: مردمک نقطه‌ای دوطرفه، Babinski دوطرفه، افزایش تون ← ثابت وسط، هایپرونتیلاسیون و decorticate؛ cerebellotonsillar: فلج شل، برادیکاردی، ایست تنفسی، مرگ ناگهانی","نافذ: GSW و اجسام تیز؛ شدت بسته به انرژی، مسیر، پراکندگی قطعات و توده"],"ddx":[{"n":"Cervical spine injury / other life-threatening injuries |","cm":1},{"n":"Intoxication / hypoglycemia / seizure / medical cause of coma |"},{"n":"Penetrating brain injury / cerebral venous sinus injury |"}],"redflags":["GCS ≤ 8، مردمک نامساوی/ثابت، پوسچرینگ، Cushing، هیپوتانسیون، CSF leak"],"guide":"1) پروتکل استاندارد تروما (فصل 156)؛ جستجوی آسیب‌های دیگر. 2) اکسیژن، مانیتور و دو IV؛ TBI شدید: اینتوباسیون با RSI برای محافظت راه هوایی و جلوگیری هیپوکسمی؛ ایمبیلیزاسیون گردن و داروی القای کافی. 3) هیپوتانسیون با مرگ بالاتر: MAP 80 mmHg با کریستالوئید IV؛ ناکارآمد: وازوپرسور. 4) مشاوره فوری نوروسرجری پس از CT با آسیب داخل‌جمجمه؛ نقص عصبی جدید از EDH/SDH حاد: درمان نوروسرجری اورژانس. 5) علائم ICP بالا: سر 30° (اگر هیپوتانسیو نیست)، آرام‌بخشی کافی، اکسیژنه شریانی: mannitol 0.25 تا 1.0 g/kg IV بولوس‌های مکرر اگر هیپوتانسیو نیست؛ هیپوتانسیو یا ناکافی احیا: سالین هیپرتونیک 3% (250 mL طی 30 دقیقه). 6) hyperventilation پروفیلاکتیک توصیه نمی‌شود (ایسکمی مغز)؛ آخرین راه و موقت با PCO2 30 تا 35 mmHg. 7) herniation قریب‌الوقوع: دکمپرسیون اورژانس trephination («burr holes») وقتی همه روش‌ها شکست خورده؛ CT قبل. 8) تشنج: benzodiazepine (lorazepam) و fosphenytoin بار 18 تا 20 PE/kg IV. 9) پروفیلاکسی ضدتشنج بحث‌برانگیز: با نوروسرجری. 10) بستری نوروسرجری برای شکستگی قاعده یا نافذ (GSW/ضربه چاقو) و آنتی‌بیوتیک پروفیلاکتیک (ceftriaxone 2 g IV و vancomycin 1 g IV).","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 160: Head Trauma, pp. 880–885"},"skull-fracture-penetrating-head-injury":{"id":"skull-fracture-penetrating-head-injury","variants":[{"id":"skull-fracture-main","o":{"I":[{"t":"Noncontrast head CT (thin-cut skull base); cervical spine imaging"}],"L":[{"t":"Type and crossmatch, CBC, coagulation, glucose"}],"A":[{"t":"Ceftriaxone 2 g IV and vancomycin 1 g IV (prophylactic)","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Avoid nasal airway / nasogastric tube; head elevation; tetanus update; neurologic checks"}],"Co":[{"t":"Neurosurgery admission"}]},"name":"Basilar skull fracture / penetrating head wound","level":"I","imp":"Basilar skull fracture / penetrating head injury","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۳۰ ساله با raccoon eyes، Battle sign و خروج مایع شفاف از بینی پس از تصادف؛ یا زخم گلوله سر.","why":"CT و آنتی‌بیوتیک؛ بدون پک بینی/لوله بینی."}],"ch":"160","name":"Basilar skull fracture and penetrating head injury","name_fa":"شکستگی قاعده جمجمه و آسیب نافذ سر","cc":["head-injury"],"keywords":"basilar skull fracture, raccoon eyes, Battle sign, CSF leak, hemotympanum, penetrating head injury, gunshot wound head, prophylactic antibiotics, شکستگی قاعده جمجمه","status":"draft","features":["basilar: معمولاً بخش petrous تمپورال؛ hemotympanum، CSF otorrhea/rhinorrhea، raccoon eyes، Battle's sign؛ depressed: باز/بسته؛ نافذ: GSW و اجسام تیز"],"ddx":[{"n":"Intracranial hemorrhage / CSF leak / meningitis |","cm":1}],"redflags":["نشت CSF، hemotympanum، زخم نافذ"],"guide":"بستری نوروسرجری و آنتی‌بیوتیک پروفیلاکتیک (ceftriaxone 2 g IV و vancomycin 1 g IV).","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 160: Head Trauma, pp. 880–885"},"spinal-cord-injury":{"id":"spinal-cord-injury","variants":[{"id":"sci-neurogenic-shock","o":{"I":[{"t":"CT cervical / thoracic / lumbar spine (high-resolution; modality of choice); MRI spine (ligamentous / cord injury; SCIWORA); CXR portable; trauma imaging per Chapter 156 (exclude hemorrhage)"}],"L":[{"t":"Type and screen, CBC, BMP, ABG, lactate, troponin; urinalysis; glucose"}],"S":[{"t":"Crystalloid to exclude / treat hypovolemia","fl":[{"k":"ci","v":"avoid fluid overload"}]},{"t":"Vasopressors / inotropic support for neurogenic shock (e.g., norepinephrine; atropine for bradycardia)"},{"t":"Methylprednisolone high-dose NOT routinely recommended (harmful side effects) — discuss with spine surgeon if considered"}],"T":[{"t":"Low threshold for endotracheal intubation for injury at C5 and above (diaphragm C3–C5); strict spinal immobilization with in-line log-roll; remove collar / long board as soon as clinically appropriate"},{"t":"Complete neurologic examination (motor, pain / temperature, proprioception, reflexes, perianal sensation / wink, bulbocavernosus, sacral sparing); Foley catheter; temperature / skin protection"}],"Co":[{"t":"Spine surgery / neurosurgery (emergent); ICU; trauma surgery"}]},"name":"Spinal cord injury with neurogenic shock / high cervical injury","level":"I","imp":"Spinal cord injury, neurogenic shock","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen; intubate if C5 and above","sc":"مرد ۲۸ ساله پس از شیرجه با فلج چهار اندام، تنفس دیافراگمی، HR 48 و فشار 80/40 با پوست گرم.","why":"راه هوایی زودهنگام، رد خونریزی و وازوپرسور؛ بدون استروئید روتین."}],"ch":"161","name":"Spinal cord injury (SCI) and neurogenic shock","name_fa":"آسیب نخاع (SCI) و شوک نوروژنیک","cc":["back-neck-pain","focal-neuro","trauma-major"],"keywords":"spinal cord injury, neurogenic shock, spinal shock, Brown-Sequard, central cord syndrome, anterior cord syndrome, SCIWORA, sacral sparing, methylprednisolone, آسیب نخاع, شوک نوروژنیک","status":"draft","features":["آسیب نخاع معمولاً مکانیکی مستقیم ← خونریزی، ادم و ایسکمی؛ درد گردن/کمر؛ شکستگی ناپایدار ممکن بدون علائم نخاعی؛ پارستزی، دیسستزی، ضعف، بی‌اختیاری/احتباس و اختلال حسی؛ کامل: فقدان حس و حرکت زیر سطح (شکل‌های 161-1/161-2)؛ ناکامل (پیش‌آگهی بهتر): ممکن با «spinal shock» پنهان شود","spinal shock: از دست رفتن گذرای رفلکس‌های نخاعی زیر سطح؛ روزها تا هفته‌ها؛ neurogenic shock: از دست رفتن عصب‌دهی سمپاتیک: برادیکاردی نسبی و هیپوتانسیون؛ ابتدا خونریزی را رد کن","SCIWORA: بیشتر کودکان؛ علائم عصبی با رادیوگرافی/CT نرمال ← MRI","معاینه عصبی کامل: قدرت و تون (کورتیکواسپینال)، درد/دما (اسپینوتالامیک)، proprioception/ارتعاش (ستون خلفی)، رفلکس‌ها، حس و wink پری‌آنال، bulbocavernosus؛ «sacral sparing» = ناکامل","جدول 161-1 سندرم‌های ناکامل: anterior cord (فلج کامل زیر ضایعه با فقدان درد/دما و حفظ proprioception؛ پیش‌آگهی بد)؛ central cord (hyperextension، تنگی کانال: quadriparesis بیشتر اندام فوقانی؛ خوب)؛ Brown-Séquard (نیمه‌برش: پارزی اسپاستیک و از دست رفتن proprioception همان سمت و از دست رفتن درد/دما سمت مقابل؛ خوب)"],"ddx":[{"n":"Hemorrhagic shock (hypotension) |","cm":1},{"n":"Cervical / thoracolumbar fracture without cord injury |"},{"n":"Spinal epidural hematoma / transverse myelitis |"}],"redflags":["C5 و بالاتر (دیافراگم C3–C5)، هیپوتانسیون با برادیکاردی، نقص عصبی پیشرونده"],"guide":"شناسایی و تثبیت آسیب‌ها و پیشگیری از ثانویه. 1) راه هوایی: آستانه پایین اینتوباسیون در C5 و بالاتر؛ تورم نسج نرم در شکستگی‌های بالا. 2) هیپوتانسیون: ابتدا شوک هیپوولمیک؛ نوروژنیک اگر احتمال SCI، بدون خونریزی حاد، گرم و نسبتاً برادیکارد (ممکن حمایت اینوتروپ). 3) collar و long board به‌محض اندیکاسیون برداشته شود؛ تروما نافذ گردن با عصب سالم و هوشیار: ایمبیلیزاسیون توصیه نمی‌شود؛ log-roll با in-line. 4) شکستگی گردن: معمولاً بستری؛ احتیاطات ستون. 5) توراسیک/لومبار: انرژی بالا؛ خطر آسیب آئورت، نخاع، ارگان‌های شکم/قفسه؛ بستری یا جراح ستون؛ compression/wedge < 40% ارتفاع با مشاوره ممکن سرپایی؛ burst و Chance: بستری؛ CT. 6) ساکروم: همراه شکستگی لگن؛ اختلال مثانه/روده، رادیکولوپاتی، cauda equina؛ کوکسیکس ایزوله: ضددرد و بالش دونات. 7) استروئید با دوز بالا (methylprednisolone) دیگر روتین توصیه نمی‌شود؛ اگر مدنظر: مشورت جراح ستون. 8) ترخیص: ارزیابی کافی و بدون اندیکاسیون بستری: پیگیری 3 تا 5 روز، ضددرد و دستور بازگشت.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 161: Spine Trauma, pp. 886–891"},"cervical-spine-injury-clearance":{"id":"cervical-spine-injury-clearance","variants":[{"id":"c-spine-clearance","o":{"I":[{"t":"NEXUS or Canadian C-spine rule to decide; CT cervical spine (preferred) or plain films ≥ 3 views (lateral, odontoid, AP); MRI if neurologic deficit / suspected ligamentous injury with negative CT"}],"S":[{"t":"Analgesics (acetaminophen / opioid as needed); muscle relaxant not before cleared"}],"T":[{"t":"Cervical immobilization (collar) until cleared; log-roll with in-line stabilization; remove collar when cleared clinically / by imaging"},{"t":"Suspected ligamentous injury (reliable patients): firm foam collar, follow-up with spine surgeon in 3–5 days"}],"Co":[{"t":"Spine surgery follow-up 3–5 days; admit cervical fractures with spine precautions"}]},"name":"Blunt trauma, neck pain — decision rule (NEXUS / Canadian C-spine) and imaging","level":"II","imp":"Cervical spine injury, blunt trauma, rule-out","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۵ ساله پس از تصادف با درد گردن و حساسیت midline؛ بدون نقص عصبی.","why":"NEXUS مثبت ← CT گردن؛ collar تا ارزیابی."}],"ch":"161","name":"Cervical spine injury — clinical decision rules and imaging (NEXUS, Canadian C-spine)","name_fa":"آسیب ستون گردن — قوانین NEXUS و Canadian C-spine","cc":["back-neck-pain","trauma-major","head-injury"],"keywords":"cervical spine injury, NEXUS criteria, Canadian C-spine rule, cervical collar, CT cervical spine, ligamentous injury, hangman fracture, Jefferson fracture, odontoid fracture, ستون گردن, NEXUS","status":"draft","features":["NEXUS (جدول 161-2): نبود حساسیت midline گردن، هوشیاری نرمال (GCS 15، جهت‌یابی، به یاد آوردن 3 شیء)، نبود مسمومیت، نبود نقص عصبی کانونی، نبود آسیب حواس‌پرتی دردناک؛ Canadian C-spine (جدول 161-3): بدون تصویربرداری اگر 3 معیار: (1) عامل پرخطر نیست (سن ≥ 65، مکانیسم خطرناک: سقوط > 3 ft، axial loading، MVC سرعت بالا/رول‌اور/پرتاب، وسایل تفریحی موتوری/دوچرخه، پارستزی)؛ (2) عامل کم‌خطر (rear-end ساده، نشستن در ED، راه رفتن، شروع تأخیری درد، نبود حساسیت midline) که ارزیابی ROM را ایمن می‌کند؛ (3) توانایی چرخش فعال گردن (45° چپ و راست)","CT با وضوح بالا حساس‌تر و اختصاصی‌تر از رادیوگرافی ساده؛ در بیشتر مراکز تروما روش انتخابی؛ رادیوگرافی ساده: حداقل 3 نما (lateral، odontoid، AP)؛ هر دو ممکن آسیب لیگامانی خالص را از دست بدهند؛ flexion-extension به‌اندازه کافی حساس نیست؛ MRI حساس‌ترین برای لیگامان و بافت عصبی","جدول 161-4 آسیب‌های گردن: flexion: anterior subluxation (پایدار)، bilateral interfacetal dislocation (ناپایدار)، wedge (معمولاً پایدار)، clay-shoveler (پایدار)، flexion teardrop (ناپایدار)؛ flexion-rotation: unilateral interfacetal dislocation (پایدار)، pillar، lateral mass (ممکن ناپایدار)؛ vertical compression: Jefferson (بالقوه ناپایدار)، burst (ناپایدار)؛ hyperextension: hyperextension dislocation (ناپایدار)، avulsion قدام atlas (پایدار)، extension teardrop (ناپایدار)، posterior arch atlas (پایدار)، laminar (معمولاً پایدار)، hangman (traumatic spondylolisthesis) (ناپایدار)؛ lateral flexion: uncinate (معمولاً پایدار)؛ سایر: occipital condyle (ممکن ناپایدار)، occipitoatlantal dissociation (بسیار ناپایدار)، dens type II و III (ناپایدار)"],"ddx":[{"n":"Spinal cord injury / ligamentous injury (CT-negative) |","cm":1},{"n":"Cervical strain / muscle spasm |"}],"redflags":["نقص عصبی، حساسیت midline، مکانیسم خطرناک، سن ≥ 65، GCS < 15"],"guide":"شکستگی گردن: معمولاً بستری با احتیاط ستون. اگر آسیب لیگامانی مشکوک: بیمار معتبر می‌تواند با collar فوم سفت ترخیص و پیگیری 3 تا 5 روز با جراح ستون. ترخیص بدون اندیکاسیون بستری: ضددرد و دستور بازگشت.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 161: Spine Trauma, pp. 886–891"},"thoracolumbar-sacral-spine-fracture":{"id":"thoracolumbar-sacral-spine-fracture","variants":[{"id":"thoracolumbar-fracture-main","o":{"I":[{"t":"CT thoracic and lumbar spine (standard; defines extent / stability); CXR (aortic / thoracic injury); abdominal imaging per mechanism"}],"L":[{"t":"Urinalysis (hematuria), CBC"}],"S":[{"t":"Analgesia (opioid / acetaminophen)","fl":[{"k":"ci","v":"avoid NSAIDs if bleeding risk"}]}],"T":[{"t":"Spine precautions / log-roll; assess for associated injuries (aorta, intra-abdominal, thoracic organs); neurologic examination incl. rectal tone"}],"Co":[{"t":"Spine surgeon: admit acute fractures; compression / wedge < 40% height loss may be outpatient with spine surgeon consult; burst and Chance fractures admitted"},{"t":"Isolated coccyx fracture: pain control and rubber doughnut pillow; sacral fractures with bladder / bowel dysfunction — admit"}]},"name":"Thoracic / lumbar vertebral fracture","level":"II","imp":"Thoracolumbar spine fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"PA","sc":"مرد ۴۰ ساله پس از سقوط از نردبان با درد کمر و حساسیت T12–L1؛ بدون نقص عصبی.","why":"CT و بررسی آسیب‌های همراه؛ burst/Chance بستری."}],"ch":"161","name":"Thoracic, lumbar and sacral spine fractures","name_fa":"شکستگی ستون توراسیک، لومبار و ساکروم","cc":["back-neck-pain","trauma-major"],"keywords":"thoracolumbar fracture, compression fracture, burst fracture, Chance fracture, sacral fracture, coccyx fracture, شکستگی مهره, burst","status":"draft","features":["شکستگی‌های توراسیک و لومبار پرانرژی؛ خطر آسیب آئورت، نخاع، ارگان‌های شکم/قفسه؛ CT استاندارد در بیشتر مراکز (حساس‌تر؛ تعیین وسعت و پایداری)؛ رادیوگرافی ساده در آسیب خفیف","ساکروم: غیرمعمول؛ همراه شکستگی لگن؛ اختلال مثانه/روده، رادیکولوپاتی و cauda equina؛ کوکسیکس ایزوله: ضددرد و بالش دونات"],"ddx":[{"n":"Aortic / abdominal organ injury / spinal cord injury |","cm":1},{"n":"Osteoporotic compression fracture / pathologic fracture |"}],"redflags":["نقص عصبی، burst/Chance fracture، شکستگی لگن همراه، خطر cauda equina"],"guide":"اغلب شکستگی حاد: بستری یا مدیریت توسط جراح ستون؛ compression/wedge با < 40% کاهش ارتفاع با مشاوره جراح ممکن سرپایی؛ burst و Chance: بستری؛ CT.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 161: Spine Trauma, pp. 886–891"},"facial-fractures":{"id":"facial-fractures","variants":[{"id":"facial-fracture-airway-hemorrhage","o":{"I":[{"t":"CT face (axial / coronal), head CT, CT cervical spine; CXR portable; Panorex / mandible CT for mandible fractures"}],"L":[{"t":"Type and crossmatch, CBC, coagulation; glucose"}],"S":[{"t":"IV crystalloid / blood as needed; tranexamic acid if major hemorrhage","fl":[{"k":"ci","v":"caution"}]},{"t":"Antibiotics for sinus / open fractures: first-generation cephalosporin, clindamycin, or amoxicillin-clavulanate","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Secure airway: orotracheal intubation preferred (not nasotracheal); plan for difficult airway; avoid paralytics unless can bag effectively or alternative plan; awake intubation option; emergent cricothyroidotomy if impossible; LMA only temporizing"},{"t":"Posterior epistaxis: nasal tampons, dual balloon devices, or Foley with layered anterior gauze packing (avoid intracranial placement in severe midface fractures); oral packing for hard palate fractures; reduction of displaced Le Fort / nasal fractures; embolization / ligation if persistent"},{"t":"Barton bandage for mandible fracture with stable airway; cervical spine precautions"}],"Co":[{"t":"Facial surgery / OMFS / ENT; neurosurgery (NOE, frontal sinus, Le Fort II/III CSF leak); ophthalmology; admit for IV antibiotics and surgical repair"}]},"name":"Severe facial trauma — airway and hemorrhage control (midface / mandible)","level":"I","imp":"Severe facial trauma with airway / hemorrhage risk","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مرد ۳۰ ساله پس از تصادف با صورت دراز، حرکت میان‌صورت، malocclusion، خونریزی دهان/بینی و خروج CSF.","why":"راه هوایی دشوار، کنترل خونریزی و CT."},{"id":"facial-fracture-stable","o":{"I":[{"t":"CT face; Waters' view if CT unavailable (low-risk); orbital CT 1.5-mm cuts"}],"S":[{"t":"Amoxicillin-clavulanate PO (sinus / orbital fractures), decongestants; analgesia"}],"T":[{"t":"Avoid nose blowing until defect repaired; examine eyes (visual acuity, EOM, pupil, fluorescein, IOP only if no globe injury); document infraorbital nerve sensation; tongue blade test / occlusion"}],"Co":[{"t":"Facial surgery follow-up (isolated zygomatic arch elective repair; closed mandible urgent outpatient follow-up; isolated anterior table frontal sinus fracture discharge with facial surgeon follow-up); emergent ophthalmology if ocular injury / orbital fissure or apex syndrome"}]},"name":"Isolated facial fracture (zygomatic arch, anterior frontal sinus, closed mandible, orbital blowout) — outpatient pathway","level":"III","imp":"Isolated facial fracture","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۲۵ ساله با ضربه مشت به گونه: تخت شدن آرچ زیگوما یا دوبینی هنگام نگاه به بالا؛ بدون آسیب چشم.","why":"CT و آنتی‌بیوتیک؛ پیگیری جراح."}],"ch":"162","name":"Facial injuries and facial fractures (mandible, zygoma, Le Fort, orbital, frontal sinus, NOE)","name_fa":"آسیب‌ها و شکستگی‌های صورت (فک، زیگوما، Le Fort، اربیت، سینوس فرونتال، NOE)","cc":["head-injury","trauma-major"],"keywords":"facial trauma, Le Fort fracture, mandible fracture, zygomatic tripod fracture, orbital blowout, frontal sinus fracture, naso-orbito-ethmoid, Barton bandage, شکستگی صورت, لفورت, فک پایین","status":"draft","features":["آسیب شدید صورت: همراه آسیب مغز، اربیت، ستون گردن و ریه؛ پس از تثبیت survey اولیه: survey ثانویه برای آسیب‌های موثر بر ظاهر، بینایی، بویایی، جویدن و حس","جدول 162-1: شرح حال: دوبینی دوچشمی ← گیرافتادن عضلات خارج‌چشمی؛ یک‌چشمی ← دررفتگی عدسی؛ بی‌حسی صورت ← عصب supraorbital/infraorbital/mental؛ malocclusion ← شکستگی فک؛ بازرسی: «dish face» (Le Fort III)، «donkey face» (Le Fort II/III)، اگزوفتالموس (retrobulbar hematoma)، enophthalmos (blowout) یا تخت شدن ملاج گونه (آرچ زیگوما)، raccoon eyes و Battle sign ظرف ساعات (قاعده جمجمه)؛ لمس: step-off، حساسیت، crepitus سینوس؛ لمس داخل‌دهانی آرچ زیگوما؛ سنجش Le Fort با تکان ملایم کام سخت و تثبیت پیشانی","چشم: زود قبل از تورم پلک؛ حدت بینایی؛ چربی از زخم پلک ← سوراخ orbital septum؛ telecanthus ← NOE؛ hypertelorism ← دررفتگی اربیت و اغلب نابینایی؛ حرکات خارج‌چشمی (محدودیت نگاه بالا: راست تحتانی/اوبلیک تحتانی یا عصب سوم)؛ مردمک اشک‌قطره‌ای (پارگی کره)، هایفما، APD، فلورسئین؛ IOP فقط بدون آسیب کره","بینی: crepitus سینوس؛ هماتوم سپتوم؛ گوش: هماتوم لاله؛ CSF، پارگی مجرا و hemotympanum ← قاعده جمجمه؛ دهان: انحراف فک، malocclusion، دندان‌های آسیب‌دیده، پارگی مخاط و اکیموز ← فک؛ آزمون tongue blade","تصویربرداری (جدول 162-2): فرونتال: CT سر (پنجره جمجمه)؛ میان‌صورت: Waters یا CT صورت با برش کرونال و آگزیال؛ فک: Panorex یا CT فک؛ CT صورت اغلب تشخیص قطعی؛ برش کرونال نیاز به پاک‌سازی گردن","فرونتال سینوس: نادر؛ نیروی زیاد ← TBI، شکستگی دیگر و C-spine؛ جدار خلفی چسبیده به دورا: ترمیم جراحی شکستگی through-and-through؛ depressed: بستری و آنتی‌بیوتیک IV و جراحی؛ ایزوله جدار قدامی: ترخیص با پیگیری جراح صورت","NOE: ضربه شدید پل بینی: آسیب مجرای اشکی، پارگی دورا و TBI: بستری با مشاوره جراحی صورت و نوروسرجری","blowout: ضربه کند به کره ← دیواره داخلی/تحتانی؛ جراحی در گیرافتادن عضله/عصب یا enophthalmos قابل‌توجه؛ superior orbital fissure: orbital fissure syndrome؛ optic nerve: orbital apex syndrome (مشاوره اورژانس چشم)؛ ocular compartment syndrome با retrobulbar hematoma یا آمفیزم اربیت بدخیم","zygoma: tripod (infraorbital rim، zygomaticofrontal، zygomaticotemporal) ← بستری، آنتی‌بیوتیک IV، جراحی؛ isolated arch: ترمیم الکتیو سرپایی","میان‌صورت: پرانرژی، چند‌سیستمی؛ اغلب اینتوباسیون؛ شکستگی کام سخت: پک دهانی؛ Le Fort I (آلوئولار)، II (زیگوماتیک-ماگزیلاری)، III (craniofacial dysjunction)؛ حدت بینایی (Le Fort III/IV نابینایی 3%)؛ Le Fort II/III: CSF leak؛ بستری، آنتی‌بیوتیک IV و جراحی","فک: malocclusion و درد حرکت؛ دنبال شکستگی‌های متعدد (محل ضربه + طرف مقابل حلقه)؛ معاینه دقیق داخل‌دهانی (پارگی مخاط = open fracture، هماتوم زیرزبانی، آلوئول)؛ بسته: پیگیری فوری سرپایی؛ باز: بستری، آنتی‌بیوتیک IV و جراحی؛ Barton bandage (آیس رپ از بالای سر و زیر فک) در راه هوایی پایدار"],"ddx":[{"n":"Airway obstruction / hemorrhage (sphenopalatine, greater palatine) |","cm":1},{"n":"Globe injury / retrobulbar hematoma / basilar skull fracture / TBI / C-spine |","cm":1},{"n":"Dental / alveolar injury / soft tissue laceration |"}],"redflags":["راه هوایی تهدیدشده، خونریزی شدید، کاهش بینایی، CSF leak، ناپایداری میان‌صورت"],"guide":"در survey اولیه: راه هوایی را تأمین و تثبیت؛ اینتوباسیون اوروتراکئال بر نازوتراکئال؛ همیشه راه هوایی دشوار فرض شود؛ شل‌کننده فقط اگر بیمار با bag قابل تهویه یا برنامه جایگزین؛ awake intubation با sedation و بی‌حسی موضعی؛ ناموفق/غیرممکن: cricothyroidotomy؛ LMA موقت (محافظت آسپیراسیون ندارد). خونریزی شدید میان‌صورت/فک از شاخه‌های sphenopalatine و greater palatine شریان کاروتید خارجی: epistaxis خلفی: tampon، بالون دوگانه یا Foley با پک قدامی (پرهیز از جایگذاری داخل‌جمجمه)؛ گاه جا انداختن شکستگی جابه‌جا؛ ادامه: جراحی/embolization. شکستگی سینوس: آنتی‌بیوتیک خوراکی/IV (سفالوسپورین نسل 1، clindamycin یا amoxicillin-clavulanate). blowout ایزوله: amoxicillin-clavulanate خوراکی، ضداحتقان و پرهیز از فین کردن تا ترمیم؛ مشاوره اورژانس چشم در آسیب چشم.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 162: Facial Injuries, pp. 892–896"},"neck-trauma-penetrating-blunt":{"id":"neck-trauma-penetrating-blunt","variants":[{"id":"neck-trauma-penetrating-unstable","o":{"I":[{"t":"CXR portable / bedside ultrasound (pneumothorax / hemothorax; 20%); no delay of OR for tests; MDCTA only if stable"}],"L":[{"t":"Type and crossmatch, CBC, coagulation, ABG / lactate"}],"S":[{"t":"Crystalloid / blood products per resuscitation; tranexamic acid 1 g IV over 10 min then 1 g IV over 8 h in exsanguinating patients with wound < 3 h","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Emergent airway control (stridor, expanding hematoma, shock); adjunct airway devices at hand; paralytics with extreme caution; surgical airway if oral intubation not possible"},{"t":"Direct pressure with hemostatic dressing without occluding carotid or airway; Foley balloon in wound tract if direct pressure fails; NO blind clamping; needle thoracostomy for tension pneumothorax then tube thoracostomy"},{"t":"Cervical immobilization only if altered mental status / neuro deficit (do not impede monitoring or life-saving procedures)"}],"Co":[{"t":"Emergent surgery / interventional radiology (do not delay egress from ED); ICU"}]},"name":"Penetrating neck trauma — hard signs / unstable (OR / angiography)","level":"I","imp":"Penetrating neck trauma, unstable / hard signs","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مرد ۲۵ ساله با ضربه چاقو گردن زون II، خونریزی ضربان‌دار، هماتوم در حال گسترش، استریدور و فشار 80/50.","why":"راه هوایی و کنترل خونریزی و اتاق عمل فوری؛ بدون تأخیر."},{"id":"neck-trauma-stable","o":{"I":[{"t":"Multidetector CT angiography (MDCTA; 100% sensitive / 97.5% specific) of the neck; esophagram + esophagoscopy (combined 100% sensitive) if pharyngoesophageal suspicion; panendoscopy / laryngobronchoscopy for laryngotracheal suspicion; cerebral angiography if MDCTA negative but suspicion remains"},{"t":"CXR PA; CT cervical spine for blunt mechanism"}],"L":[{"t":"CBC, coagulation, type and screen"}],"A":[{"t":"IV antibiotics for 7–10 days if pharyngoesophageal injury confirmed (with nasogastric or TPN nutrition / repair or conservative management)"}],"T":[{"t":"ATLS monitoring; observation 4–6 h for asymptomatic blunt neck trauma (delayed respiratory / neurologic dysfunction), especially with BCVI risk factors; address psychosocial issues of strangulation victims (hanging / strangulation: MDCTA liberal)"}],"Co":[{"t":"Surgical consultation for all platysma-violating wounds and symptomatic blunt trauma (admit even if initial study negative); penetrating wounds not violating platysma: standard wound care and discharge if asymptomatic"}]},"name":"Neck trauma, stable — platysma violation / CTA / blunt screening","level":"II","imp":"Neck injury, stable (penetrating platysma violation / blunt)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۳۵ ساله پایدار با زخم نافذ گردن که platysma را شکافته؛ یا بیمار تصادف با کمربند و گردن‌درد.","why":"MDCTA و مشاوره جراحی؛ مشاهده در بلانت."}],"ch":"163","name":"Neck injuries — penetrating and blunt (vascular, laryngotracheal, pharyngoesophageal), strangulation","name_fa":"آسیب‌های گردن — نافذ و بلانت و خفگی","cc":["trauma-major","ent","back-neck-pain"],"keywords":"penetrating neck trauma, zones of neck, platysma, CT angiography, blunt cerebrovascular injury, laryngotracheal injury, strangulation, hanging, tranexamic acid, آسیب گردن, خفگی, ناحیه گردن","status":"draft","features":["تروما به گردن ← ترکیب آسیب‌های متنوع؛ علائم ممکن آشکار، ظریف یا پنهان؛ آسیب‌های از دست رفته ← مرگ‌ومیر","جدول 163-1: علائم سخت (90% نیاز به ترمیم اورژانس): عروقی: شوک مقاوم به مایع، خونریزی شریانی فعال، کمبود نبض، هماتوم ضربان‌دار/در حال گسترش، thrill یا bruit؛ حنجره-نای: استریدور، هموپتیزی، دیسفونی، هوا/حباب در زخم، انسداد راه هوایی؛ فارنکس-مری: (بدون علائم سخت)؛ نرم: هیپوتانسیون در صحنه، سابقه خونریزی شریانی، هماتوم غیرضربان‌دار، زخم مجاور؛ خشونت صدا، حساسیت گردن، آمفیزم زیرجلدی، اکیموز/هماتوم، انحراف نای یا step-off غضروف، ادم/هماتوم حنجره، محدودیت حرکت طناب صوتی؛ odynophagia، dysphagia، hematemesis، خون در دهان، خروج بزاق از زخم، حساسیت شدید گردن، هوای prevertebral، مسیر transmidline","آسیب عروقی شایع‌ترین آسیب گردن و علت مرگ در تروما نافذ؛ جدول 163-2 غربالگری blunt cerebrovascular injury: خونریزی شریانی از بینی/گردن/دهان، bruit گردن < 50 سال، هماتوم در حال گسترش، نقص عصبی کانونی (TIA، همی‌پارزی، Horner)، سکته در CT ثانویه، نقص بدون توضیح CT، مکانیسم انرژی بالا + شکستگی صورت (Le Fort II/III، فک، فرونتال، اربیت)، الگوی شکستگی ستون گردن (subluxation، transverse foramen، C1–C3)، شکستگی قاعده/occipital condyle/petrous، DAI با GCS ≤ 8، TBI + قفسه، hanging، clothesline","حنجره-نای: انسداد راه هوایی فوری یا بروز مخفی؛ جدول 163-3 اندیکاسیون مدیریت تهاجمی راه هوایی: استریدور، دیسترس حاد تنفسی، انسداد با خون/ترشح، هماتوم در حال گسترش، شوک عمیق، آمفیزم زیرجلدی وسیع، تغییر هوشیاری، انحراف نای","فارنکس و مری: بدون علائم سخت و علائم اولیه اندک؛ عصبی: ستون گردن، نخاع، اعصاب کرانیال پایین، شبکه بازوی؛ خفگی (strangulation): فشار عروقی بیشتر از انسداد راه هوایی؛ آنوکسی مغز، شکستگی حنجره/نای/ستون، پارگی فارنکس و آسیب کاروتید؛ علائم: درد گردن، تغییر صدا، دیسفاژی، تنگی نفس؛ نشانه‌ها: پتشی و کبودی گردن؛ 50% بدون علامت تروما و 67% بدون علامت؛ برخی آسیب کشنده بدون علامت","زون‌ها (شکل 163-1): I: راس ریه، عروق توراسیک، نای دیستال، مری، ستون، شریان‌های ورتبرال و کاروتید؛ II: کاروتید و ورتبرال میانی، ورید ژوگولار، مری، ستون، حنجره و نای؛ III: کاروتید و ورتبرال پروگزیمال، اوروفارنکس، ستون","نافذ: معاینه ساختارمند > 95% حساس؛ پارگی platysma ← فرض آسیب عمق؛ MDCTA (100% حساس و 97.5% اختصاصی) + معاینه در پایدار؛ الگوریتم شکل 163-2؛ بلانت: MDCTA آزادانه؛ منفی با شک: آنژیوگرافی؛ شک حنجره/مری: laryngobronchoscopy، اندوسکوپی یا مطالعه بلع"],"ddx":[{"n":"Vascular injury / expanding hematoma / airway obstruction |","cm":1},{"n":"Cervical spine / spinal cord injury / tension pneumothorax |","cm":1},{"n":"Pharyngoesophageal injury (occult) |"}],"redflags":["علائم سخت، استریدور، هماتوم در حال گسترش، شوک، پارگی platysma، transmidline"],"guide":"1) پروتکل ATLS؛ IV، اکسیژن و مانیتور. 2) کنترل اورژانس راه هوایی: اندیکاسیون جدول 163-3؛ ابزار کمکی آماده؛ شل‌کننده با احتیاط شدید؛ اگر اوروتراکئال غیرممکن: راه هوایی جراحی. 3) تروما نافذ گردن: 20% pneumothorax/hemothorax؛ tension: سوزن‌گذاری فوری؛ سونوگرافی/CXR و tube thoracostomy. 4) فشار مستقیم با پانسمان هموستاتیک بدون انسداد کاروتید یا راه هوایی؛ clamp کور ممنوع؛ هموستاتیک موضعی؛ Foley در مسیر زخم و باد کردن؛ tranexamic acid 1 g IV طی 10 دقیقه سپس 1 g طی 8 ساعت در بیمار در حال خونریزی کشنده با زخم < 3 ساعت؛ ادامه: جراحی اورژانس. 5) ایمبیلیزاسیون گردن در تغییر هوشیاری، تروما بلانت یا نافذ با نقص عصبی پس از معاینه دقیق. 6) هر زخم نافذ که platysma را بشکافد: مشاوره جراحی؛ ناپایدار: جراحی/رادیولوژی مداخله‌ای اورژانس؛ پایدار: ارزیابی تشخیصی (شکل 163-2). 7) بدون نفوذ platysma: مراقبت استاندارد و بستن؛ ترخیص در بدون علامت. 8) بلانت با علائم سخت: مشاوره جراحی اورژانس؛ پایدار علامت‌دار: MDCTA؛ بستری و مشاوره حتی با مطالعه اولیه منفی. 9) بلانت بدون علامت: MDCTA آزادانه و مشاهده طولانی (4 تا 6 ساعت)؛ به‌ویژه عوامل خطر BCVI. 10) مسائل روانی-اجتماعی در strangulation.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 163: Neck Injuries, pp. 897–902"},"tension-pneumothorax-traumatic":{"id":"tension-pneumothorax-traumatic","variants":[{"id":"pneumothorax-tension","o":{"I":[{"t":"Clinical diagnosis — do not wait for imaging; after decompression CXR / bedside ultrasound (loss of sliding pleura) to confirm; CT if stable"}],"L":[{"t":"ABG, CBC, type and crossmatch"}],"S":[{"t":"Resuscitation per trauma protocol (IV access, crystalloid / blood as needed)","fl":[{"k":"ci","v":"avoid over-resuscitation"}]}],"T":[{"t":"Needle decompression: 14-G, 4.5-cm over-the-needle catheter at second intercostal space midclavicular line (rush of air confirms); leave catheter in until chest tube inserted; then tube thoracostomy (24–28 F for pneumothorax) — never clamp tube; water seal when off suction"},{"t":"Open chest wound: sterile petroleum gauze taped on three sides; chest tube not through the wound"}],"Co":[{"t":"Trauma surgery / thoracic surgery; ICU / admit"}]},"name":"Tension pneumothorax (needle decompression)","level":"I","imp":"Tension pneumothorax, traumatic","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مصدوم ضربه چاقو به قفسه با تنگی نفس شدید، ورید گردن متسع، فشار 70/40 و صدای تنفسی ناپدید در سمت چپ.","why":"تشخیص بالینی و سوزن‌گذاری فوری."},{"id":"pneumothorax-simple-hemothorax","o":{"I":[{"t":"Upright / expiratory CXR (supine insensitive; hemothorax < 200 mL, up to 1000 mL appear as haziness); bedside ultrasound; CT chest highly sensitive"},{"t":"Repeat ultrasound / CXR at 4–6 h for stab wounds (delayed pneumothorax)"}],"L":[{"t":"CBC, type and crossmatch, ABG"}],"S":[{"t":"Analgesia (IV opioid / intercostal nerve block)"}],"T":[{"t":"Large pneumothorax: tube thoracostomy 24–28 F; small pneumothorax: inpatient observation; any pneumothorax or subcutaneous emphysema in patient to be intubated or air-transported: tube thoracostomy"},{"t":"Hemothorax: tube thoracostomy (32–40 F historically; larger may not be necessary); heparinized autotransfusion device if massive (do not delay tube); surgery if immediate 1 L return or ongoing 150–200 mL/h for 2–4 h"},{"t":"If lung fails to reexpand: check tubing connections, tube position, bronchial occlusion, large bronchial tear / parenchymal tear"}],"Co":[{"t":"Trauma / thoracic surgery; admit"}]},"name":"Simple pneumothorax / hemothorax — tube thoracostomy","level":"I","imp":"Pneumothorax / hemothorax, traumatic","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","o2":"100% oxygen","sc":"مرد ۴۰ ساله پس از تصادف با شکستگی دنده و پنوموتوراکس بزرگ یا هموتوراکس چپ؛ پایدار.","why":"tube thoracostomy؛ اندیکاسیون جراحی را پایش کن."}],"ch":"164","name":"Traumatic pneumothorax (tension, open, simple) and hemothorax","name_fa":"پنوموتوراکس تروماتیک (تنشنی، باز، ساده) و هموتوراکس","cc":["trauma-major","dyspnea","chest-pain"],"keywords":"tension pneumothorax, needle decompression, open pneumothorax, chest tube, tube thoracostomy, hemothorax, subcutaneous emphysema, پنوموتوراکس تنشنی, لوله سینه","status":"draft","features":["tension: ورود هوا به فضای پلورال از ریه آسیب‌دیده، نای/برونش یا زخم باز؛ فشار مثبت با تنفس ← اختلال تنفسی و گردش خون؛ تنگی نفس، تاکی‌کاردی، هیپوتانسیون، ورید گردن متسع، انحراف نای و صداهای تنفسی نامساوی","زخم باز کوچک می‌تواند با اثر دریچه یک‌طرفه به tension تبدیل شود","پنوموتوراکس کوچک: بستری مشاهده؛ بزرگ: tube thoracostomy (24 تا 28 F)؛ هر اندازه یا آمفیزم زیرجلدی (پنوموتوراکس مخفی) در بیماری که اینتوبه می‌شود یا با هوا منتقل می‌شود: tube thoracostomy (فشار مثبت و کاهش فشار بارومتریک ← گسترش هوای محبوس)؛ chest tube هرگز clamp نشود و با برداشتن ساکشن روی water seal","جدول 164-2 علل شکست انبساط کامل: اتصالات نادرست یا نشت، موقعیت نامناسب لوله، انسداد برونش با ترشح/جسم خارجی، پارگی برونش بزرگ، پارگی بزرگ پارانشیم","هموتوراکس: tube thoracostomy (تاریخی 32 تا 40 F، بزرگ ممکن لازم نباشد)؛ اندیکاسیون جراحی: بازگشت فوری 1 L خون یا خونریزی مداوم 150 تا 200 mL/h برای 2 تا 4 ساعت؛ autotransfusion هپارینه در هموتوراکس ماسیو ولی بدون تأخیر tube","CXR supine حساسیت پایین برای پنوموتوراکس و هموتوراکس < 200 mL (تا 1000 mL به‌صورت تیرگی منتشر)؛ upright و expiratory حساس‌تر؛ سونوگرافی: از بین رفتن sliding pleura؛ CT بسیار حساس؛ زخم نافذ هرگز عمیق پروب نشود؛ تکرار سونوگرافی/CXR 4 تا 6 ساعت بعد (تأخیری)"],"ddx":[{"n":"Cardiac tamponade / massive hemothorax |","cm":1},{"n":"Mainstem intubation / diaphragmatic rupture |","cm":1},{"n":"Tracheobronchial injury / pulmonary contusion |"}],"redflags":["شوک، ورید گردن متسع، انحراف نای، صدای تنفسی یکطرفه، SpO2 پایین"],"guide":"tension: تشخیص بالینی و سوزن‌گذاری فوری بدون انتظار رادیوگرافی: کاتتر 14G و 4.5 cm در فضای بین‌دنده‌ای دوم خط میدکلاویکولار (کاتتر معمول 14G ممکن به پلور نرسد)؛ هجوم هوا تأییدکننده؛ کاتتر تا قرار دادن chest tube بماند (tension را به open تبدیل می‌کند). زخم باز: گاز وازلینه استریل با چسب سه‌طرفه؛ tube thoracostomy نه از زخم. ساب‌کلاوین: اگر cannulation سمت آسیب انجام شود تا pneumothorax iatrogenic دوطرفه نشود.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 164: Cardiothoracic Injuries, pp. 903–908"},"pulmonary-contusion-flail-rib":{"id":"pulmonary-contusion-flail-rib","variants":[{"id":"pulm-contusion-flail","o":{"I":[{"t":"CXR (contusion often not visible initially; patchy opacities within 6 h); CT chest (more sensitive); bedside ultrasound; ECG"}],"L":[{"t":"ABG, CBC, troponin (sternal fracture / blunt cardiac), type and screen"}],"S":[{"t":"Analgesia: IV opioids, intercostal nerve blocks or epidural anesthesia"},{"t":"Crystalloid judiciously; early blood products; diuretics if volume overload","fl":[{"k":"ci","v":"avoid unnecessary IV fluids (pulmonary edema)"}]}],"T":[{"t":"Strict pulmonary toilet; incentive spirometry; trial of mask positive pressure ventilation if normal mental status and limited need; intubation and PPV with PEEP for flail chest / > 25% lung involvement / respiratory failure (not preemptive); cardiac monitoring for sternal fracture","fl":[{"k":"ci","v":"no taping or binding of chest wall"}]}],"Co":[{"t":"Admit (multiple fractures, comorbidities, older age) until pain controlled and pulmonary toilet stable; trauma surgery; ICU if ventilated"}]},"name":"Pulmonary contusion / flail chest (ventilatory support)","level":"I","imp":"Pulmonary contusion / flail chest","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","o2":"titrate to SpO2 ≥ 94%","sc":"مرد ۵۵ ساله پس از تصادف با حرکت پارادوکس دیواره قفسه، درد شدید و SpO2 88%.","why":"مسکن، pulmonary toilet و تهویه در لزوم."},{"id":"rib-fracture-discharge","o":{"I":[{"t":"Upright CXR; ultrasound (pneumothorax); evaluate for pneumothorax, pulmonary contusion, intraabdominal injury"}],"S":[{"t":"NSAIDs and opioid analgesics; intercostal nerve block if needed","fl":[{"k":"ci","v":"NSAIDs — renal disease / bleeding"}]}],"T":[{"t":"Deep breathing / incentive spirometry; do not tape or bind chest wall"}],"Co":[{"t":"Discharge with return precautions; admit if multiple fractures, comorbidities, older age"}]},"name":"Isolated rib fractures — discharge pathway","level":"III","imp":"Rib fractures","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مرد ۳۵ ساله جوان با شکستگی ایزوله دنده 7 و 8 پس از سقوط؛ علائم حیاتی طبیعی، بدون پنوموتوراکس.","why":"ضددرد و تنفس عمیق؛ ترخیص."}],"ch":"164","name":"Pulmonary contusion, flail chest and rib fractures","name_fa":"کوفتگی ریه، flail chest و شکستگی دنده","cc":["chest-pain","dyspnea","trauma-major"],"keywords":"pulmonary contusion, flail chest, rib fractures, intercostal nerve block, incentive spirometry, sternal fracture, کوفتگی ریه, شکستگی دنده","status":"draft","features":["کوفتگی ریه: آسیب مستقیم پارانشیم بدون پارگی؛ هیپوکسی با خونریزی و ادم؛ 70% در CXR اولیه دیده نمی‌شود و ظرف 6 ساعت لکه‌های پراکنده؛ CT بسیار حساس‌تر","flail chest: شکستگی چندمحلی دنده‌ها ← بی‌ثباتی بخش دیواره؛ خطر بزرگ‌تر: کوفتگی ریه زیرین","شکستگی دنده: دنده اول و دوم نیروی زیاد ← شک بالا برای آسیب قلب/عروق/برونش؛ دنده‌های تحتانی متعدد ← کبد/طحال؛ درد ← splinting، اختلال تهویه و پنومونی؛ استرنوم: ECG، troponin سریال و مانیتور قلبی","جدول 164-1 اندیکاسیون حمایت تهویه زودهنگام: تغییر وضعیت ذهنی، شوک هیپوولمیک، آسیب‌های متعدد، ترانسفیوژن متعدد، سالمند، بیماری ریوی قبلی، دیسترس تنفسی، SpO2 پایین، کوفتگی ریه شدید"],"ddx":[{"n":"Pneumothorax / hemothorax / cardiac contusion |","cm":1},{"n":"Liver / splenic injury (lower rib fractures) |","cm":1}],"redflags":["شکستگی دنده اول/دوم، flail segment، SpO2 پایین، سالمند"],"guide":"کوفتگی ریه: کنترل درد برای جلوگیری از هیپوونتیلاسیون، پرهیز از مایع IV غیرضروری (ادم ریه)، pulmonary toilet دقیق؛ کریستالوئید محتاطانه و زودتر فرآورده خونی؛ ماسک فشار مثبت آزمایشی اگر هوشیار و حمایت محدود؛ درگیری > 25% ریه احتمالاً اینتوباسیون ولی نه پیشگیرانه؛ PEEP اگر اینتوبه؛ دیورتیک در اضافه‌بار. flail: اینتوباسیون و تهویه فشار مثبت بخش را تثبیت می‌کند؛ ممکن fixation جراحی؛ ببندی/نوار برای تثبیت دیواره ممنوع. دنده: بلوک عصب بین‌دنده‌ای و اپیدورال؛ ترخیص: NSAID و اوپیوئید؛ تنفس عمیق/incentive spirometry؛ بستری: دنده‌های متعدد، بیماری همراه یا سن بالا.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 164: Cardiothoracic Injuries, pp. 903–908"},"tracheobronchial-diaphragm-esophageal-injury":{"id":"tracheobronchial-diaphragm-esophageal-injury","variants":[{"id":"thoracic-visceral-injury","o":{"I":[{"t":"CXR (gastric tube coiled in chest, herniation); CT chest / abdomen; bronchoscopy for tracheobronchial; water-soluble contrast esophagram then barium if negative, or flexible esophagoscopy; upper GI series; laparoscopy / laparotomy gold standard for diaphragm"}],"L":[{"t":"CBC, type and screen, ABG"}],"S":[{"t":"IV fluids and analgesia","fl":[{"k":"ci","v":"caution in volume overload"}]}],"A":[{"t":"IV broad-spectrum antibiotics if esophageal / tracheobronchial injury or mediastinitis suspected"}],"T":[{"t":"NPO; chest tube for pneumothorax / hemothorax / chylothorax; airway protection (intubation selective)"}],"Co":[{"t":"Thoracic / trauma surgery (all diaphragmatic lacerations require repair); ICU"}]},"name":"Suspected tracheobronchial / diaphragmatic / esophageal injury","level":"I","imp":"Thoracic visceral injury (tracheobronchial / diaphragm / esophagus)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مصدوم ضربه نافذ زیر نوک پستان چپ با درد قفسه؛ یا پس از تصادف با آمفیزم گردن و نشت هوای ماسیو از chest tube.","why":"CT/برونکوسکوپی/اندوسکوپی و جراحی؛ NPO."}],"ch":"164","name":"Pneumomediastinum, tracheobronchial, diaphragmatic and esophageal / thoracic duct injuries","name_fa":"پنوموومدیاستن و آسیب نای/برونش، دیافراگم، مری و مجرای توراسیک","cc":["trauma-major","chest-pain","dyspnea"],"keywords":"tracheobronchial injury, diaphragmatic rupture, esophageal injury, chylothorax, pneumomediastinum, water-soluble contrast esophagram, آسیب نای, پارگی دیافراگم, آسیب مری","status":"draft","features":["پنوموومدیاستن: اغلب پارگی آلوئول با نفوذ هوا؛ بدون درمان در بدون علامت؛ سرفه/تنفس عمیق/ورزش؛ آسیب نای و راه‌های هوایی بزرگ: انرژی بالا/کاهش شتاب: دیسپنه، هموپتیزی، آمفیزم زیرجلدی گردن، صدای crunching با چرخه قلب و نشت هوای ماسیو مداوم از chest tube","دیافراگم: همه آسیب‌های نافذ از سطح نوک پستان تا ناف؛ پارگی کوچک بدون علامت و هفته‌ها تا ماه‌ها بعد فتق احشا؛ تشخیص: فتق در تصویربرداری یا کلاف لوله معده در قفسه؛ لاپاراتومی/لاپاراسکوپی استاندارد طلایی؛ همه پارگی‌ها ترمیم جراحی","مری/مجرای توراسیک: نافذ و گاه بلانت: اگر مشکوک: esophagram با کنتراست محلول در آب (مدیاستینیت کمتر)؛ منفی ← باریم (حساس‌تر)؛ یا اندوسکوپی؛ تأخیر ← مرگ‌ومیر بالا با مدیاستینیت؛ ناحیه ورید ساب‌کلاوین چپ پروگزیمال ← chylothorax (مرگ‌ومیر 50%): chest tube"],"ddx":[{"n":"Tension pneumothorax / aortic injury |","cm":1},{"n":"Esophageal rupture (Boerhaave) / mediastinitis |"}],"redflags":["آمفیزم گردن، نشت هوای ماسیو، تیره شدن قفسه چپ، hematemesis، mediastinitis"],"guide":"pneumomediastinum بدون علامت: درمانی ندارد. تراکئوبرونشیال: برونکوسکوپی و جراحی. دیافراگم: جراحی. مری: esophagram/اندوسکوپی و جراحی/NPO و آنتی‌بیوتیک؛ chylothorax: chest tube اولیه.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 164: Cardiothoracic Injuries, pp. 903–908"},"cardiac-trauma-tamponade-thoracotomy":{"id":"cardiac-trauma-tamponade-thoracotomy","variants":[{"id":"cardiac-tamponade-penetrating","o":{"I":[{"t":"Bedside ultrasound (eFAST) — pericardial fluid; CXR portable (do not delay)"}],"L":[{"t":"Type and crossmatch (O-negative emergency), CBC, coagulation, ABG / lactate"}],"S":[{"t":"Blood / crystalloid resuscitation; temporizing measures","fl":[{"k":"ci","v":"avoid over-resuscitation"}]}],"T":[{"t":"Pericardiocentesis only for patient in shock with confirmed tamponade (technically difficult; risk of coronary / myocardial laceration); stable: pericardial window or thoracotomy in OR"},{"t":"ED thoracotomy for penetrating chest injury with signs of life in field who become pulseless: relieve tamponade, control hilar bleeding, cross-clamp descending aorta, repair myocardial laceration; temporize lacerations with digital pressure, staples, sutures, or Foley balloon"}],"Co":[{"t":"Trauma / cardiothoracic surgery immediately; ICU"}]},"name":"Penetrating cardiac injury with tamponade (shock) / ED thoracotomy","level":"I","imp":"Penetrating cardiac injury, cardiac tamponade","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مرد ۲۵ ساله با ضربه چاقو به قفسه چپ، فشار 60/40، ورید گردن متسع و صداهای قلب خفه؛ اکو: مایع پریکارد.","why":"پریکاردیوسنتز فقط در شوک تأییدشده؛ پایدار ← OR؛ بی‌نبض ← توراکوتومی."},{"id":"blunt-cardiac-injury","o":{"I":[{"t":"Bedside echocardiography (tamponade, gross contractility); formal echocardiography (TEE ~ 3× more sensitive than TTE for blunt myocardial injury); CXR"}],"L":[{"t":"ECG, troponin (serial), CBC, electrolytes"}],"S":[{"t":"Antiarrhythmic and inotropic medications per ACLS algorithms; analgesia"},{"t":"Pericarditis (2–4 weeks after cardiac trauma / surgery): NSAIDs"}],"T":[{"t":"Continuous cardiac monitoring; ACLS for commotio cordis (VF; usually no structural damage); ECG ischemia → catheterization and stenting (coronary dissection / thrombosis)"}],"Co":[{"t":"Admit if echo / ECG / enzyme abnormality; discharge if normal vitals, normal initial ECG, no cardiac disease and age < 55 after 4–6 h normal monitoring; cardiology"}]},"name":"Blunt cardiac injury / commotio cordis / post-traumatic pericarditis","level":"II","imp":"Blunt cardiac injury","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۳۰ ساله پس از فرمان به قفسه با درد قفسه، تاکی‌کاردی، PVC و ST تغییر؛ یا ورزشکار پس از ضربه توپ با ایست VF (commotio).","why":"ECG، troponin و اکو؛ ACLS در VF."}],"ch":"164","name":"Cardiac trauma (penetrating cardiac injury, tamponade, blunt cardiac injury, commotio cordis, pericarditis)","name_fa":"ترومای قلب (نافذ، تامپوناد، آسیب بلانت، commotio cordis)","cc":["trauma-major","chest-pain","hypotension-shock"],"keywords":"cardiac tamponade, penetrating cardiac injury, ED thoracotomy, blunt cardiac injury, myocardial contusion, commotio cordis, pericardiocentesis, تامپوناد, ترومای قلب","status":"draft","features":["نافذ: بطن راست بیشتر (سطح قدامی بزرگ)؛ خون در پریکارد قلب را فشرده و پر شدن دیاستولی را مختل می‌کند؛ تشخیص با سونوگرافی بالین؛ پریکاردیوسنتز فقط در بیمار شوکه با تامپوناد تأییدشده (مشکل فنی؛ خطر پارگی کرونر/میوکارد)؛ پایدار: pericardial window یا توراکوتومی در اتاق عمل","ED thoracotomy: نافذ قفسه با علائم حیات در صحنه که بی‌نبض شده: رفع تامپوناد، کنترل خونریزی هیلار، کراس‌کلمپ آئورت نزولی، ترمیم میوکارد؛ stab بیشتر از GSW قابل ترمیم؛ بازکردن قفسه: قلب از پریکارد خارج؛ فشار انگشتی، staple، بخیه یا Foley با بالون برای موقت","بلانت: مرگ از آسیب ساختار قلب، آسیب و ترومبوز کرونر، کوفتگی میوکارد (اختلال انقباض و آریتمی)؛ تغییر ECG ایسکمیک ← دیسکسیون/ترومبوز کرونر (کاتتریزاسیون و stent)؛ commotio cordis: ضربه مستقیم (مثلاً توپ سخت) ← VF بدون آسیب میوکارد: ACLS؛ تظاهر: درد قفسه، تاکی‌کاردی غیرمرتبط با خونریزی، آریتمی؛ اکو بالین: غربالگری اول تامپوناد و اختلال شدید انقباض؛ هیپوتانسیون بی‌توضیح، آریتمی، اختلال انقباض: اکو رسمی و آنزیم؛ TEE 3 برابر TTE حساس‌تر؛ آنتی‌آریتمیک و اینوتروپ طبق ACLS؛ بستری: غیرطبیعی بودن اکو/ECG/آنزیم؛ ترخیص: علائم حیاتی نرمال، ECG اولیه نرمال، بدون بیماری قلبی و سن < 55 بعد 4 تا 6 ساعت مانیتور نرمال","پریکاردیت پس از ترومای قلب/جراحی 2 تا 4 هفته: درد قفسه، تب، friction rub، ST elevation منتشر؛ افیوژن پریکارد/پلور؛ درمان NSAID"],"ddx":[{"n":"Tension pneumothorax / massive hemothorax / aortic injury |","cm":1},{"n":"Acute coronary syndrome / pericarditis |"}],"redflags":["شوک، ورید گردن متسع، Beck triad، زخم نافذ ناحیه قلب (box)، آریتمی بدون توضیح"],"guide":"بلانت: تامپوناد مثل نافذ؛ آنتی‌آریتمیک و اینوتروپ طبق ACLS. پایدار نافذ: پنجره پریکارد/توراکوتومی در OR. پریکاردیت: NSAID.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 164: Cardiothoracic Injuries, pp. 903–908"},"blunt-aortic-great-vessel-injury":{"id":"blunt-aortic-great-vessel-injury","variants":[{"id":"blunt-aortic-injury-main","o":{"I":[{"t":"CT angiogram of chest with IV contrast (all patients with mechanism highly concerning); conventional aortography in some cases; TEE for intimal lesions (contraindicated in airway compromise / suspected C-spine injury); CXR portable (normal does not exclude)"}],"L":[{"t":"Type and crossmatch, CBC, coagulation, ABG / lactate, troponin"}],"S":[{"t":"Titrated opioid analgesia and sedatives; esmolol titrated to SBP 100–120 mmHg and HR > 60 ; if bradycardia prevents further β-blocker: sodium nitroprusside infusion","fl":[{"k":"hi","v":""},{"k":"ci","v":"do not use nitroprusside without β-blocker (reflex tachycardia); caution esmolol in shock"}]},{"t":"Blood products if hemorrhage"}],"T":[{"t":"Avoid hypertension (shear stress); cardiac monitoring"}],"Co":[{"t":"Vascular / cardiothoracic surgery (immediate operation if hemodynamic instability, rapidly expanding hematoma, large chest tube output); ICU"}]},"name":"Suspected blunt aortic / great vessel injury","level":"I","imp":"Blunt aortic / great vessel injury","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد ۳۰ ساله پس از تصادف سرعت بالا با CXR: مدیاستن پهن و محو شدن knob آئورت؛ HR 105 و فشار 150/90.","why":"CTA فوری، کنترل فشار و HR؛ جراحی عروق."}],"ch":"164","name":"Blunt aortic and great vessel injury","name_fa":"آسیب بلانت آئورت و عروق بزرگ","cc":["trauma-major","chest-pain"],"keywords":"blunt aortic injury, aortic transection, great vessel injury, mediastinal widening, CT angiogram, esmolol, nitroprusside, آسیب آئورت, عروق بزرگ","status":"draft","features":["ترومای عروق بزرگ توراسیک اغلب کشنده؛ 90% آسیب بلانت آئورت در صحنه می‌میرند؛ شایع‌ترین محل: آئورت نزولی پروگزیمال بین ساب‌کلاوین چپ و ligamentum arteriosum؛ ساب‌کلاوین و innominate: کمربند شانه، شکستگی دنده 1 و 2 و کلاویکل پروگزیمال؛ نیمی بدون علائم خارجی: شک بالا در کاهش شتاب با سرعت بالا","جدول 164-3 رادیوگرافی: شکستگی استرنوم، اسکاپولا، دنده‌های متعدد، کلاویکل در چندسیستمی، دنده اول و دوم؛ علائم مدیاستن: محو شدن کانتور knob آئورت، پهن شدن مدیاستن، فشار برونش اصلی چپ، از بین رفتن paravertebral stripe، کلسیم لایه‌ای روی knob، ظاهر غیرطبیعی مدیاستن، انحراف NG به راست، جابه‌جایی جانبی نای؛ سایر: apical cap، هموتوراکس چپ ماسیو، آسیب واضح دیافراگم؛ CXR نرمال آسیب عروقی را رد نمی‌کند","مکانیسم نگران‌کننده: CT آنژیوگرام با کنتراست IV؛ آئورتوگرافی در برخی موارد؛ TEE برای ضایعه intima (ممنوع در مشکل راه هوایی یا شک آسیب ستون گردن)"],"ddx":[{"n":"Tension pneumothorax / cardiac tamponade / hemothorax |","cm":1},{"n":"Aortic dissection (spontaneous) |"}],"redflags":["ناپایداری، مدیاستن پهن، هموتوراکس چپ ماسیو، شکستگی دنده اول/دوم"],"guide":"اندیکاسیون عمل فوری: ناپایداری همودینامیک، هماتوم در حال گسترش سریع در تصویربرداری، حجم بالای chest tube. کنترل هیپرتانسیون برای کاهش stress دیواره: تیتر مسکن اوپیوئیدی و آرام‌بخش؛ β-blocker کوتاه‌اثر (esmolol) تا SBP 100 تا 120 و HR > 60؛ اگر برادیکاردی مانع دوز بیشتر: وازودیلاتور شریانی sodium nitroprusside؛ nitroprusside بدون β-blocker (تاکی‌کاردی رفلکسی) ممنوع.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 164: Cardiothoracic Injuries, pp. 903–908"},"abdominal-trauma-blunt":{"id":"abdominal-trauma-blunt","variants":[{"id":"abdominal-trauma-unstable","o":{"I":[{"t":"eFAST (free intraperitoneal fluid; pericardial / pleural fluid; pneumothorax) — repeat serially; CXR portable (free air, diaphragm); AP pelvis radiograph"},{"t":"CT only if hemodynamically stable; DPL only if too unstable for CT with equivocal exam / unexplained hypotension (not if surgery clearly indicated)"}],"L":[{"t":"Type and crossmatch, CBC, electrolytes, lactate, coagulation studies, hepatic enzymes, lipase, ABG, directed toxicology"}],"S":[{"t":"IV crystalloid to hypotensive patients; transfuse O-negative or type-specific PRBC as indicated ; massive transfusion protocol; tranexamic acid","fl":[{"k":"hi","v":""}]},{"t":"Two large-bore IV lines"}],"T":[{"t":"Oxygen, cardiac monitoring; keep warm; immediate transport to OR (Table 165-4 indications: hypotension with anterior abdominal injury, peritonitis, free air, disruption, positive FAST / DPL in unstable)"}],"Co":[{"t":"Emergent trauma surgery / laparotomy; ICU; interventional radiology for embolization if appropriate"}]},"name":"Blunt abdominal trauma with hypotension / positive FAST (laparotomy)","level":"I","imp":"Blunt abdominal trauma, hemodynamically unstable","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مرد ۳۰ ساله پس از تصادف با فشار 75/45، HR 135، شکم متسع و FAST مثبت.","why":"خون و جراحی فوری؛ بدون CT."},{"id":"abdominal-trauma-stable-ct","o":{"I":[{"t":"CT abdomen / pelvis with IV contrast (noninvasive gold standard; multiphasic CT for mesenteric hemorrhage / bowel injury); CXR; AP pelvis; ultrasound (FAST)"}],"L":[{"t":"Type and crossmatch, CBC (serial hemoglobin), electrolytes, lactate, creatinine, hepatic enzymes, lipase, coagulation, urinalysis, directed toxicology"}],"S":[{"t":"Crystalloid for hypotension only; IV analgesia"}],"T":[{"t":"Cardiac monitoring; serial abdominal examinations (awake, reliable patient); NPO"}],"Co":[{"t":"Trauma surgery admission (solid organ injury, hemoperitoneum without clear source = relative laparotomy indication); observation / ICU as indicated"}]},"name":"Blunt abdominal trauma, hemodynamically stable (CT, serial exams)","level":"II","imp":"Blunt abdominal trauma, stable","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۲۵ ساله پس از تصادف با درد LUQ و کتف چپ (Kehr)، شکستگی دنده چپ؛ فشار 120/80 و FAST مثبت.","why":"CT شکم-لگن با کنتراست و معاینات سریال."}],"ch":"165","name":"Blunt abdominal trauma (solid organ, hollow viscus, retroperitoneal, diaphragm injuries)","name_fa":"ترومای بلانت شکم (ارگان‌های توپر، توخالی، رتروپریتوان، دیافراگم)","cc":["trauma-major","abdominal-pain"],"keywords":"blunt abdominal trauma, FAST exam, splenic injury, liver injury, Kehr sign, duodenal injury, pancreatic injury, CT abdomen contrast, diagnostic peritoneal lavage, laparotomy, ترومای شکم, طحال, FAST","status":"draft","features":["هدف: تشخیص سریع آسیب‌هایی که نیاز به اکتشاف جراحی فوری دارند؛ بزرگ‌ترین خطا: به تأخیر انداختن جراحی در زمان لزوم","ارگان توپر: عوارض و مرگ عمدتاً از خونریزی؛ افزایش pulse pressure ممکن تنها سرنخ ≤ 15% حجم خون؛ HR و RR با ادامه افزایش؛ هیپوتانسیون در 30% کاهش؛ طحال شایع‌ترین آسیب در تروما بلانت؛ کبد در بلانت و نافذ؛ Kehr sign (درد ارجاعی شانه چپ) کلاسیک پارگی طحال؛ شکستگی دنده تحتانی چپ ← شک طحال؛ علائم حداقل در جوان و آسیب حواس‌پرتی/سر/مسمومیت؛ معاینه سریال در بیمار هوشیار و معتبر","ارگان توخالی: ترکیب خونریزی و آلودگی پریتوان؛ سوراخ معده/روده/کولون + آسیب مزانتر؛ علائم پریتونیت با گذشت زمان (6 تا 8 ساعت)؛ سر/حواس‌پرتی/مسمومیت: ممکن اولاً علائم نداشته باشد؛ روده کوچک و کولون بیشتر نافذ ولی کاهش شتاب: bucket-handle مزانتر یا blow-out لبه آنتی‌مزانتریک","رتروپریتوان: تشخیص چالش‌برانگیز؛ دوازدهه: کاهش شتاب سرعت بالا؛ هماتوم intramural تا ازهم‌گسیختگی؛ علائم دیررس: درد، تب، تهوع، استفراغ؛ پانکراس: کاهش شتاب سریع/فشار شدید؛ فرمان یا handlebar؛ علائم ظریف","دیافراگم: تظاهر پنهان؛ فتق احشا یا NG در قفسه در CXR؛ اغلب فقط محو شدن دیافراگم یا افیوژن","CXR: فتق، هوای آزاد زیر دیافراگم؛ AP لگن: شکستگی لگن؛ FAST (جدول 165-1): مایع آزاد؛ سریع (< 4 دقیقه)، غیرتهاجمی، تکرارپذیر، بدون پرتو؛ پریکارد و پلور و pneumothorax؛ محدودیت: عامل مایع نامعلوم، وابسته به اپراتور، چاقی/هوا، فرقی بین خون و آسیت، رتروپریتوان ضعیف؛ تقریباً DPL را در بلانت جایگزین کرده؛ CT شکم-لگن با کنتراست IV استاندارد طلایی (مکان و درجه دقیق؛ دوازدهه و پانکراس؛ multiphasic: خونریزی مزانتر و آسیب ترانس‌مورال)؛ PO contrast وقت‌گیر؛ DPL: ناپایدار نمی‌تواند برای CT برود یا هیپوتانسیون بی‌توضیح با معاینه مبهم؛ مثبت: > 10 mL خون خام، RBC > 100,000، WBC > 500، صفرا یا مواد گیاهی؛ ممنوع مطلق: جراحی واضح؛ نسبی: بیماری کبدی پیشرفته، کوآگولوپاتی شدید، جراحی قبلی، رحم باردار","جدول 165-4 اندیکاسیون لاپاراتومی (بلانت): مطلق: آسیب قدام شکم با هیپوتانسیون، disruption دیواره، پریتونیت، هوای آزاد زیر دیافراگم، FAST/DPL مثبت در ناپایدار، آسیب نیازمند جراحی در CT (قطع پانکراس، پارگی دوازدهه، دیافراگم)؛ نسبی: FAST/DPL مثبت در پایدار، آسیب ارگان توپر در پایدار، hemoperitoneum در CT بدون منبع روشن"],"ddx":[{"n":"Hemorrhagic shock (thoracic, pelvic, retroperitoneal) |","cm":1},{"n":"Aortic / great vessel / diaphragm injury |"}],"redflags":["هیپوتانسیون، پریتونیت، FAST مثبت، هوای آزاد، شکستگی لگن، seat belt sign"],"guide":"1) پروتکل استاندارد تروما (فصل 156). 2) اکسیژن، مانیتور و دو IV بزرگ. 3) هیپوتانسیو: کریستالوئید IV و O-منفی یا PRBC type-specific. 4) آزمایش: type and crossmatch، CBC، الکترولیت، لاکتات، توکسیکولوژی، انعقاد، آنزیم کبد، lipase. 5) لاپاراتومی اندیکاسیون جدول 165-4؛ GSW سرعت بالا آشکار شکم: بدون تأخیر FAST مگر شک آسیب قلب؛ evisceration: پانسمان استریل مرطوب. 7) بلانت پایدار با FAST مثبت: CT قبل از بستری جراحی.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 165: Abdominal Injuries, pp. 909–913"},"abdominal-trauma-penetrating":{"id":"abdominal-trauma-penetrating","variants":[{"id":"penetrating-abdominal-unstable","o":{"I":[{"t":"CXR portable; do not delay OR for FAST unless cardiac injury suspected (precordial wound)"}],"L":[{"t":"Type and crossmatch, CBC, lactate, coagulation, electrolytes"}],"S":[{"t":"IV crystalloid / blood products; tranexamic acid","fl":[{"k":"hi","v":""}]}],"A":[{"t":"Broad-spectrum antibiotics (pre-op; e.g., cefazolin + metronidazole or piperacillin/tazobactam 3.375 g IV)"}],"T":[{"t":"Cover eviscerated organs with moist sterile dressing; two large-bore IV; oxygen; tetanus"}],"Co":[{"t":"Immediate trauma surgery (laparotomy); ICU"}]},"name":"Penetrating abdominal trauma — unstable / peritonitis / GSW (OR)","level":"I","imp":"Penetrating abdominal trauma requiring laparotomy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"100% oxygen","sc":"مرد ۲۰ ساله با گلوله شکم، فشار 80/50، حساسیت شکم و evisceration روده.","why":"OR فوری؛ پانسمان مرطوب و آنتی‌بیوتیک."},{"id":"penetrating-abdominal-stab-stable","o":{"I":[{"t":"eFAST; CXR; CT abdomen / pelvis with IV contrast if equivocal and stable"}],"L":[{"t":"CBC, lactate"}],"T":[{"t":"Surgical consultation for local wound exploration; serial abdominal exams"}],"Co":[{"t":"Trauma surgery; discharge if no violation of anterior fascia on local wound exploration (and stable serial examinations)"}]},"name":"Stab wound to abdomen, stable (local wound exploration)","level":"II","imp":"Stab wound abdomen, stable","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مرد ۳۰ ساله با زخم چاقو 2 cm قدام شکم، پایدار، بدون حساسیت.","why":"اکتشاف موضعی توسط جراح؛ اگر fascia سالم ترخیص."}],"ch":"165","name":"Penetrating abdominal trauma (stab wound / gunshot wound)","name_fa":"ترومای نافذ شکم (چاقو / گلوله)","cc":["trauma-major","wound-bite","abdominal-pain"],"keywords":"penetrating abdominal trauma, gunshot wound abdomen, stab wound abdomen, evisceration, local wound exploration, laparotomy, ضربه چاقو شکم, گلوله شکم","status":"draft","features":["سوراخ‌شدن معده/روده/کولون و خونریزی مزانتر؛ اندیکاسیون لاپاراتومی نافذ (جدول 165-4): مطلق: آسیب شکم/پشت/فلانک با هیپوتانسیون، حساسیت شکم، evisceration، شک بالا به مسیر transabdominal پس از GSW، آسیب نیازمند جراحی در CT؛ نسبی: local wound exploration مثبت پس از stab"],"ddx":[{"n":"Hemothorax / cardiac injury / diaphragm injury |","cm":1}],"redflags":["هیپوتانسیون، پریتونیت، evisceration، GSW transabdominal"],"guide":"GSW سرعت بالا آشکار شکم: بدون تأخیر انتقال به OR با FAST مگر شک آسیب قلب؛ evisceration: پانسمان استریل مرطوب قبل جراحی. stab مبهم: مشاوره جراحی برای local wound exploration؛ اگر fascia قدامی سالم: ترخیص.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 165: Abdominal Injuries, pp. 909–913"},"flank-buttock-penetrating-trauma":{"id":"flank-buttock-penetrating-trauma","variants":[{"id":"flank-penetrating-main","o":{"I":[{"t":"CT abdomen / pelvis with IV contrast (± PO or rectal contrast if hollow viscus suspected; helps determine stab wound depth); eFAST (free fluid predicts need for surgery)"}],"L":[{"t":"CBC, lactate, creatinine, urinalysis (hematuria), type and screen, rectal examination (gross blood)"}],"S":[{"t":"IV crystalloid if needed"}],"A":[{"t":"Piperacillin/tazobactam 3.375 g IV if peritoneal violation concern / peritonitis","fl":[{"k":"ci","v":"penicillin allergy"}]}],"T":[{"t":"Standard trauma resuscitation; observation with serial exams; tetanus"}],"Co":[{"t":"Trauma surgery: emergent laparotomy for hemodynamic instability, peritonitis or gunshot wound to flank; high-risk stab (beyond deep fascia) admit; low-risk (superficial to deep fascia) discharge if serial exams unremarkable"}]},"name":"Penetrating flank trauma (stable — CT; unstable / GSW — OR)","level":"I","imp":"Penetrating flank trauma","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۲۸ ساله با ضربه چاقو فلانک چپ، پایدار؛ هماچوری میکروسکوپی.","why":"CT و خطر؛ ناپایدار/GSW ← OR."},{"id":"buttock-penetrating-main","o":{"I":[{"t":"CT abdomen / pelvis with oral, IV and rectal contrast (avoid missed colon / rectal injury); cystourethrogram for hematuria / wounds near GU tract; CT angiography / angiography and venography if pelvic hematoma; eFAST"}],"L":[{"t":"CBC, lactate, type and crossmatch, urinalysis (hematuria); rectal exam (gross blood), lower-extremity pulses, sciatic / femoral nerve examination"}],"S":[{"t":"IV crystalloid / blood if unstable"}],"A":[{"t":"Piperacillin/tazobactam 3.375 g IV if peritonitis or high suspicion for peritoneal violation"}],"T":[{"t":"Standard resuscitation; interventional angiography for extensive intrapelvic bleeding; wound exploration of limited value; tetanus"}],"Co":[{"t":"Trauma surgery: laparotomy if unstable, peritonitis, or likely intrapelvic / transabdominal bullet path; most patients admitted for observation (occult injuries); very superficial stab wounds only may be discharged"}]},"name":"Penetrating buttock trauma","level":"I","imp":"Penetrating buttock trauma","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"مرد ۲۲ ساله با گلوله باسن بالای تروکانتر بزرگ و هماچوری.","why":"CT سه‌گانه و cystourethrogram؛ GSW نیاز جراحی بالا."}],"ch":"166","name":"Penetrating trauma to the flank and buttocks","name_fa":"ترومای نافذ فلانک و باسن","cc":["trauma-major","wound-bite","flank-pain"],"keywords":"penetrating flank trauma, penetrating buttock trauma, retroperitoneal injury, gunshot flank, CT triple contrast, piperacillin tazobactam, ضربه نافذ فلانک, باسن","status":"draft","features":["چالش: تشخیص آسیب پریتوان و رتروپریتوان؛ تعیین نیاز به جراحی فوری؛ مسیرها و شدت متنوع (stab و GSW)؛ ناپایدار: جراحی فوری؛ مکانیسم، زمان، سلاح، مسیر گلوله یا عمق زخم در تصمیم","فلانک: از علائم حیاتی پایدار با زخم بی‌خطر تا شوک و پریتونیت؛ خون خام رکتال ← آسیب روده؛ خون در مئاتوس یا هماچوری ← آسیب ادراری-تناسلی؛ CT انتخابی در پایدار (ممکن PO یا رکتال برای آسیب توخالی؛ تعیین عمق stab)؛ eFAST برای مایع آزاد","باسن: GSW بسیار بیشتر از stab نیاز لاپاراتومی؛ GSW بالای تروکانتر بزرگ و هماچوری پیش‌بینی جراحی؛ معاینه رکتال، نبض‌های اندام تحتانی و عصبی (سیاتیک و فمورال)؛ CT با کنتراست خوراکی، IV و رکتال؛ cystourethrogram در هماچوری یا نزدیک مسیر ادراری؛ CTA یا آنژیوگرافی/venography اگر هماتوم لگن"],"ddx":[{"n":"Retroperitoneal / intraperitoneal / vascular / urinary tract injury |","cm":1}],"redflags":["ناپایداری، پریتونیت، GSW فلانک، مسیر transabdominal/intrapelvic، هماچوری"],"guide":"فلانک: لاپاراتومی اورژانس: ناپایدار، پریتونیت، GSW فلانک. شک سوراخ پریتوان یا پریتونیت: آنتی‌بیوتیک وسیع‌الطیف piperacillin/tazobactam 3.375 g IV. بسیاری stab محافظه‌کارانه: پرخطر (عمق بیش از fascia عمقی): مشاوره جراحی و بستری؛ کم‌خطر (سطحی‌تر از fascia عمقی): ترخیص اگر معاینات سریال بی‌یافته و پایدار پس از مشاهده. باسن: ناپایدار، پریتونیت یا مسیر intrapelvic/transabdominal: لاپاراتومی؛ آنژیوگرافی مداخله‌ای در خونریزی داخل لگن؛ اکتشاف زخم محدود ارزش؛ فقط stab بسیار سطحی ترخیص؛ بیشتر بستری و مشاهده (آسیب پنهان).","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 166: Penetrating Trauma to The Flank and Buttocks, pp. 914–915"},"genitourinary-trauma-upper":{"id":"genitourinary-trauma-upper","variants":[{"id":"renal-injury-major","o":{"I":[{"t":"CT abdomen / pelvis with IV contrast including 10-minute delayed image (extravasation); eFAST; CXR; AP pelvis radiograph"}],"L":[{"t":"Type and crossmatch, CBC (repeat Hct), urinalysis (repeat), electrolytes, lactate, coagulation studies"}],"S":[{"t":"IV crystalloid / blood products as needed for hypotension","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Hydration, bed rest; serial Hct and urinalysis; analgesia"}],"Co":[{"t":"Urology / trauma surgery: surgery for life-threatening bleeding, expanding / pulsatile / noncontained hematoma, renal avulsion, extravasation; otherwise admit for observation"}]},"name":"Renal injury — high grade / gross hematuria / unstable (admit or OR)","level":"I","imp":"Renal injury (blunt/penetrating trauma), gross hematuria","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۳۰ ساله پس از تصادف با درد فلانک و هماچوری ماکروسکوپی.","why":"CT با کنتراست و تأخیری؛ بستری برای Hct و UA مجدد؛ ناپایدار/هماتوم در حال بزرگ‌شدن ← جراحی."},{"id":"renal-injury-microhematuria","o":{"I":[{"t":"No imaging if no imaging indication (Table 167-1); CT with IV contrast if indications present"}],"L":[{"t":"Urinalysis, CBC"}],"T":[{"t":"No strenuous activity; follow-up in 1 to 2 weeks for repeat urinalysis"}],"Co":[{"t":"Outpatient urology / primary care follow-up"}]},"name":"Microscopic hematuria without imaging indication (discharge)","level":"III","imp":"Blunt trauma, microscopic hematuria","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"PA","sc":"زن ۲۵ ساله پس از ضربه فلانک، هماچوری میکروسکوپی، علائم حیاتی پایدار، بدون اندیکاسیون تصویربرداری.","why":"ترخیص با پیگیری 1 تا 2 هفته و UA مجدد."},{"id":"ureteral-injury-main","o":{"I":[{"t":"CT with delayed images; IVP or retrograde pyelogram if CT nondiagnostic"}],"L":[{"t":"CBC, urinalysis, creatinine"}],"T":[{"t":"Trauma resuscitation; NPO"}],"Co":[{"t":"Urology / trauma surgery for operative repair"}]},"name":"Ureteral injury (delayed CT; operative)","level":"II","imp":"Suspected ureteral injury","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۲۸ ساله با زخم نافذ شکم/فلانک و شک نشت ادرار.","why":"CT تأخیری؛ تشخیص با IVP یا retrograde؛ درمان جراحی."}],"ch":"167","name":"Renal and ureteral injury","name_fa":"آسیب کلیه و حالب","cc":["trauma-major","flank-pain","urinary-symptoms"],"keywords":"renal trauma, kidney injury, ureteral injury, hematuria after trauma, CT with delayed images, renal laceration, آسیب کلیه, هماچوری بعد از تروما, آسیب حالب","status":"draft","features":["کلیه: شایع‌ترین آسیب ژنیتوارینری؛ هماچوری (ماکروسکوپی یا میکروسکوپی) نشانه اصلی؛ شدت هماچوری لزوماً با شدت آسیب هم‌خوان نیست","تصویربرداری: CT با کنتراست IV و تصویر تأخیری 10 دقیقه (برای نشت ادرار)؛ جدول 167-1","اندیکاسیون جراحی: خونریزی تهدیدکننده حیات، هماتوم در حال بزرگ‌شدن/ضربان‌دار/غیرمحصور، avulsion، extravasation","حالب: آسیب نادر و اغلب نافذ؛ CT تأخیری؛ اگر غیرتشخیصی: IVP یا retrograde pyelogram؛ درمان جراحی"],"ddx":[{"n":"Bladder / urethral injury |","cm":1},{"n":"Intra-abdominal solid organ injury (liver, spleen) |","cm":1},{"n":"Pelvic fracture with hemorrhage |"}],"redflags":["هماچوری ماکروسکوپی، هیپوتانسیون، هماتوم در حال بزرگ‌شدن، شکستگی لگن"],"guide":"1) پروتکل ترومای فصل 156. 2) CT با کنتراست IV + تصویر تأخیری 10 دقیقه. 3) هماچوری میکروسکوپی بدون اندیکاسیون تصویربرداری: ترخیص با فعالیت سبک و پیگیری 1 تا 2 هفته برای UA مجدد. 4) درجه بالاتر یا هماچوری ماکروسکوپی: بستری برای Hct/UA مجدد، هیدراتاسیون، استراحت.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 167: Genitourinary Injuries, pp. 916–919"},"genitourinary-trauma-lower":{"id":"genitourinary-trauma-lower","variants":[{"id":"bladder-rupture-main","o":{"I":[{"t":"AP pelvis radiograph; retrograde cystogram (about 350 mL contrast); CT cystography"}],"L":[{"t":"CBC, urinalysis, creatinine, type and screen"}],"T":[{"t":"Extraperitoneal rupture: catheter drainage; intraperitoneal rupture: surgical repair"}],"Co":[{"t":"Urology / trauma surgery"}]},"name":"Bladder injury (gross hematuria / pelvic fracture)","level":"II","imp":"Suspected bladder rupture","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۳۵ ساله پس از ترومای لگن با هماچوری ماکروسکوپی و شکستگی لگن.","why":"cystogram رتروگراد و درناژ یا ترمیم."},{"id":"urethral-injury-main","o":{"I":[{"t":"Retrograde urethrogram with 20 to 30 mL contrast (16G angiocatheter if Foley already in place); AP pelvis radiograph"}],"L":[{"t":"CBC, urinalysis, creatinine, type and screen"}],"T":[{"t":"Posterior urethral injury: suprapubic drainage and repair in weeks, no Foley before retrograde urethrogram; anterior injury: supportive management"}],"Co":[{"t":"Urology"}]},"name":"Urethral injury (retrograde urethrogram before Foley)","level":"II","imp":"Suspected urethral injury (blood at meatus / pelvic fracture)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۴۰ ساله پس از ضربه به لگن با خون در میتوس و ناتوانی در ادرار.","why":"قبل از Foley حتماً urethrogram."}],"ch":"167","name":"Bladder and urethral injury","name_fa":"آسیب مثانه و پیشابراه","cc":["trauma-major","urinary-symptoms","genital-complaint"],"keywords":"bladder rupture, urethral injury, retrograde cystogram, retrograde urethrogram, pelvic fracture hematuria, blood at meatus, آسیب مثانه, آسیب پیشابراه, سیستوگرام رتروگراد","status":"draft","features":["مثانه: حدود 2% از ترومای بلانت شکم؛ 80% با شکستگی لگن همراه؛ هماچوری ماکروسکوپی ← retrograde cystogram (حدود 350 mL کنتراست)","پارگی extraperitoneal: درناژ با کاتتر؛ پارگی intraperitoneal: ترمیم جراحی","پیشابراه خلفی: درناژ suprapubic، ترمیم پس از هفته‌ها؛ پیش از retrograde urethrogram نباید Foley گذاشت","پیشابراه قدامی: urethrogram با 20 تا 30 mL کنتراست (angiocatheter 16G اگر Foley گذاشته شده)؛ درمان حمایتی"],"ddx":[{"n":"Pelvic fracture with hemorrhage |","cm":1},{"n":"Renal injury |"}],"redflags":["خون در میتوس، شکستگی لگن، ناتوانی در ادرار"],"guide":"1) شکستگی لگن + هماچوری ماکروسکوپی: retrograde cystogram. 2) خون در میتوس: ابتدا urethrogram، سپس Foley. 3) پارگی داخل‌صفاقی: جراحی؛ خارج‌صفاقی: کاتتر.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 167: Genitourinary Injuries, pp. 916–919"},"genital-trauma-male":{"id":"genital-trauma-male","variants":[{"id":"testicular-trauma-main","o":{"I":[{"t":"Scrotal Doppler ultrasound"}],"L":[{"t":"Urinalysis"}],"T":[{"t":"Ruptured testis: surgical repair; intact: ice, elevation, scrotal support, analgesia"}],"Co":[{"t":"Urology (rupture)"}]},"name":"Testicular trauma (Doppler US)","level":"II","imp":"Scrotal trauma","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"PA","sc":"مرد ۲۲ ساله پس از ضربه به اسکروتوم با تورم و درد.","why":"Doppler US؛ پارگی ← جراحی."},{"id":"penile-trauma-main","o":{"I":[{"t":"Retrograde urethrogram if urethral injury suspected (Table 167-1)"}],"L":[{"t":"Urinalysis"}],"T":[{"t":"Contusion / skin laceration: conservative; deep laceration, penetrating injury, fracture: operative; amputation: preserve part for microsurgical reimplantation"}],"Co":[{"t":"Urology (operative / microsurgical reimplantation)"}]},"name":"Penile trauma (contusion vs deep laceration / fracture / amputation)","level":"II","imp":"Penile trauma","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"PA","sc":"مرد ۳۰ ساله با تورم و دفورمیتی آلت پس از آسیب حین رابطه.","why":"کوفتگی/پارگی پوست محافظه‌کار؛ عمیق/fracture/قطع ← جراحی."}],"ch":"167","name":"Testicular and penile trauma","name_fa":"ترومای بیضه و آلت","cc":["genital-complaint","trauma-major"],"keywords":"testicular rupture, scrotal trauma, penile fracture, penile amputation, scrotal ultrasound, ترومای بیضه, شکستگی آلت, قطع آلت","status":"draft","features":["بیضه: Doppler US؛ پارگی ← ترمیم؛ آسیب بدون پارگی: یخ، elevation، حمایت، analgesia","آلت: کوفتگی/پارگی پوست: محافظه‌کارانه؛ پارگی عمقی، نافذ، قطع (reimplantation میکروسرجری)، fracture ← جراحی"],"ddx":[{"n":"Testicular torsion |","cm":1},{"n":"Urethral injury |"}],"redflags":["هماتوم رو‌به‌رشد اسکروتوم، خون در میتوس، قطع عضو"],"guide":"1) بیضه: Doppler US. 2) پارگی: ترمیم جراحی. 3) آلت: قطع ← قطعه را حفظ و reimplantation.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 167: Genitourinary Injuries, pp. 916–919"},"extremity-vascular-trauma":{"id":"extremity-vascular-trauma","variants":[{"id":"extremity-vascular-hard-signs","o":{"I":[{"t":"AP and lateral radiographs of the joint above and below; CT angiography only if stable and time allows"}],"L":[{"t":"Type and crossmatch, CBC, coagulation studies, lactate"}],"S":[{"t":"IV crystalloid / blood as needed","fl":[{"k":"hi","v":""}]}],"A":[{"t":"Penetrating fracture treated as open: IV cephalosporin plus gentamicin","fl":[{"k":"ci","v":"cephalosporin allergy"}]}],"T":[{"t":"Direct pressure or tourniquet (never clamp blindly); tetanus prophylaxis"}],"Co":[{"t":"Immediate vascular surgery; orthopedics for associated fracture"}]},"name":"Extremity trauma with hard signs of vascular injury","level":"I","imp":"Extremity trauma with vascular injury (hard signs)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۲۶ ساله با زخم نافذ ران، خونریزی شریانی و نبض دیستال غایب.","why":"کنترل خونریزی و جراح عروق فوری."},{"id":"extremity-penetrating-soft-signs","o":{"I":[{"t":"AP and lateral radiographs of the joint above and below; ABI (abnormal < 0.9) then CT angiography if abnormal"}],"L":[{"t":"Not routinely required beyond fixed set"}],"T":[{"t":"Irrigation with at least 500 to 1000 cc saline at 15 to 20 psi; wound closure for low-risk wounds with follow-up in 24 to 48 hours; contaminated wounds: delayed primary closure after 72 to 96 hours; tetanus prophylaxis; 24-hour observation if no arterial injury"}],"A":[{"t":"Antibiotics only for fracture or high-risk wounds"}],"Co":[{"t":"Vascular surgery if ABI abnormal / CTA positive; surgical consult for compartment syndrome"}]},"name":"Penetrating extremity trauma — soft signs / low risk","level":"II","imp":"Penetrating extremity wound","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"PA","sc":"زن ۳۰ ساله با زخم نافذ ساعد، نبض طبیعی، هماتوم کوچک.","why":"ABI و مشاهده؛ ریسک کم ← ترمیم و پیگیری."}],"ch":"168","name":"Extremity trauma — vascular injury (hard / soft signs) and penetrating wounds","name_fa":"ترومای اندام — آسیب عروقی (علائم قطعی / احتمالی) و زخم‌های نافذ","cc":["limb-injury","wound-bite","trauma-major"],"keywords":"extremity trauma, vascular injury, hard signs, soft signs, ankle-brachial index, CT angiography, tourniquet, compartment syndrome, penetrating extremity wound, ترومای اندام, آسیب عروقی, ABI, کمپارتمان","status":"draft","features":["علائم قطعی (hard): نبض غایب/کاهش‌یافته، خونریزی شریانی، هماتوم در حال بزرگ‌شدن/ضربان‌دار، bruit، thrill، ایسکمی دیستال ← مشاوره فوری جراحی عروق","علائم احتمالی (soft) ← ABI (غیرطبیعی < 0.9) و CTA؛ مشاهده","گرافی AP و lateral مفصل بالا و پایین ضایعه","کنترل خونریزی: فشار مستقیم یا تورنیکت؛ هرگز clamp کور","شکستگی همراه زخم نافذ مانند open fracture: debridement، سفالوسپورین IV + gentamicin","کزاز؛ شستشو با حداقل 500 تا 1000 cc سالین با فشار 15 تا 20 psi","بستن زخم: ریسک کم با پیگیری 24 تا 48 ساعت؛ زخم آلوده: delayed primary closure پس از 72 تا 96 ساعت","آنتی‌بیوتیک فقط برای شکستگی یا زخم پرخطر","24 ساعت مشاهده اگر آسیب شریانی نیست","سندرم کمپارتمان ← مشاوره جراحی"],"ddx":[{"n":"Compartment syndrome |","cm":1},{"n":"Open fracture |","cm":1},{"n":"Nerve / tendon injury |"}],"redflags":["نبض غایب، خونریزی شریانی، هماتوم در حال بزرگ‌شدن، درد شدید با کشش پاسیو"],"guide":"1) خونریزی: فشار مستقیم یا تورنیکت. 2) علائم hard ← جراح عروق فوری. 3) علائم soft ← ABI < 0.9 → CTA. 4) سایر: ترمیم و پیگیری 24 تا 48 ساعت.","section":"trauma","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 168: Trauma to The Extremities, pp. 920–922"}});
